CREATE OR REPLACE FUNCTION public.create_book_commerce_order(input_purchaser_user_id uuid, input_book_project_id uuid, input_discount_code text, input_standard_extra_copy_count integer, input_premium_copy_count integer, input_include_gift_package boolean, input_shipping_address jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 quote jsonb;
 code_row public.discount_codes%rowtype;
 campaign_row public.discount_campaigns%rowtype;
 order_row public.commerce_orders%rowtype;
 reservation_minutes integer := 60;
 used_count integer;
 snapshot jsonb := '{}'::jsonb;
begin
 if input_purchaser_user_id is null then raise exception '購入者が必要です'; end if;
 if not exists (
 select 1 from public.book_projects where id = input_book_project_id and owner_user_id = input_purchaser_user_id
 ) then raise exception 'この物語の購入手続きを開始できません' using errcode = '42501'; end if;

 select coalesce(integer_value, 60) into reservation_minutes
 from public.commerce_settings where setting_key = 'checkout_reservation_minutes';
 update public.commerce_orders set status = 'expired'
 where status = 'checkout_pending' and created_at < now() - make_interval(mins => reservation_minutes);
 update public.discount_redemptions r set status = 'released'
 where status = 'pending' and exists (
 select 1 from public.commerce_orders o where o.id = r.commerce_order_id and o.status = 'expired'
 );

 quote := public.get_book_order_quote(
 input_book_project_id, input_discount_code, input_standard_extra_copy_count,
 input_premium_copy_count, input_include_gift_package
 );

 if quote ->> 'discount_code_id' is not null then
 select * into code_row from public.discount_codes where id = (quote ->> 'discount_code_id')::uuid for update;
 select * into campaign_row from public.discount_campaigns where id = code_row.campaign_id for update;
 select count(*) into used_count from public.discount_redemptions
 where discount_code_id = code_row.id and status in ('pending', 'redeemed');
 if code_row.max_redemptions is not null and used_count >= code_row.max_redemptions then
 raise exception 'この割引コードは使用中または使用済みです' using errcode = '22023';
 end if;
 if campaign_row.one_per_account and exists (
 select 1 from public.discount_redemptions
 where campaign_id = code_row.campaign_id and purchaser_user_id = input_purchaser_user_id and status in ('pending', 'redeemed')
 ) then raise exception 'この割引は1アカウントにつき1回利用できます' using errcode = '22023'; end if;
 end if;

 select coalesce(
 (
 select to_jsonb(s)
 from public.book_cover_settings s
 where s.book_project_id = input_book_project_id
 limit 1
 ),
 '{}'::jsonb
 ) into snapshot;

 insert into public.commerce_orders(
 purchaser_user_id, book_project_id, order_type, product_code,
 amount_subtotal, gift_package_amount, discount_amount, amount_total,
 currency, discount_code_id, status,
 includes_base_book, includes_premium_hardcover,
 base_book_amount, premium_hardcover_amount, design_snapshot,
 standard_extra_copy_count, premium_copy_count,
 requested_standard_extra_copy_count, requested_premium_copy_count,
 gift_package_selected, shipping_address
 ) values (
 input_purchaser_user_id, input_book_project_id, 'self', 'self_book_v1',
 (quote ->> 'amount_subtotal')::integer, (quote ->> 'gift_package_amount')::integer,
 (quote ->> 'discount_amount')::integer, (quote ->> 'amount_total')::integer,
 'jpy', nullif(quote ->> 'discount_code_id', '')::uuid, 'checkout_pending',
 coalesce((quote ->> 'includes_base_book')::boolean, false),
 coalesce((quote ->> 'includes_premium_hardcover')::boolean, false),
 (quote ->> 'base_book_amount')::integer, (quote ->> 'premium_hardcover_amount')::integer, snapshot,
 (quote ->> 'standard_extra_copy_count_due')::integer,
 (quote ->> 'premium_copy_count_due')::integer,
 (quote ->> 'standard_extra_copy_count')::integer,
 (quote ->> 'premium_copy_count')::integer,
 coalesce((quote ->> 'gift_package_selected')::boolean, false),
 coalesce(input_shipping_address, '{}'::jsonb)
 ) returning * into order_row;

 if code_row.id is not null then
 insert into public.discount_redemptions(
 discount_code_id, campaign_id, commerce_order_id, purchaser_user_id, amount_discounted
 ) values (
 code_row.id, code_row.campaign_id, order_row.id, input_purchaser_user_id,
 (quote ->> 'discount_amount')::integer
 );
 end if;

 return jsonb_build_object('order', to_jsonb(order_row), 'quote', quote);
end;
$function$

CREATE OR REPLACE FUNCTION public.keep_story_recipient_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
 if tg_op = 'UPDATE' and new.source is distinct from old.source then
 new.source := old.source;
 new.status := old.status;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_family_story_invitation(input_claim_token text, input_book_project_id uuid, input_accept_support boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 invitation public.family_story_invitations%rowtype;
 project_row public.book_projects%rowtype;
 inviter_person_id uuid;
 current_email text := lower(btrim(coalesce(auth.jwt() ->> 'email', '')));
begin
 if auth.uid() is null then
 raise exception 'ログインが必要です' using errcode = '42501';
 end if;

 select * into invitation
 from public.family_story_invitations
 where claim_token = input_claim_token
 for update;

 if invitation.id is null or invitation.status not in (
 'ready', 'sent', 'opened', 'accepted', 'trial_started', 'trial_completed',
 'continuation_awaiting_payment', 'continuation_declined', 'started'
 ) then
 raise exception 'この家族招待は利用できません' using errcode = '22023';
 end if;
 if invitation.recipient_email is not null and lower(invitation.recipient_email) <> current_email then
 raise exception '招待されたメールアドレスでログインしてください' using errcode = '42501';
 end if;
 if invitation.recipient_user_id is not null and invitation.recipient_user_id <> auth.uid() then
 raise exception 'この家族招待は受取済みです' using errcode = '22023';
 end if;

 select * into project_row
 from public.book_projects
 where id = input_book_project_id and owner_user_id = auth.uid()
 for update;
 if project_row.id is null then
 raise exception '物語を確認できません' using errcode = '42501';
 end if;

 update public.book_projects
 set onboarding_preferences = coalesce(onboarding_preferences, '{}'::jsonb) || jsonb_build_object(
 'family_invitation_id', invitation.id,
 'family_offer_type', invitation.offer_type,
 'family_special_price_eligible', true,
 'family_inviter_user_id', invitation.inviter_user_id,
 'family_assistance_mode', invitation.assistance_mode
 ),
 updated_at = now()
 where id = project_row.id;

 if input_accept_support and invitation.assistance_mode in ('support_requested', 'recipient_chooses') then
 select person_id into inviter_person_id
 from public.user_person_links
 where user_id = invitation.inviter_user_id and role = 'self'
 order by created_at, id
 limit 1;

 insert into public.project_supporters (
 book_project_id, supporter_user_id, supporter_person_id,
 granted_by_user_id, status, can_operate_recording, can_manage_photos,
 can_edit_book_text, can_build_book, can_view_raw_audio,
 can_change_sharing, can_change_legacy, can_delete_story, meta_json
 ) values (
 project_row.id, invitation.inviter_user_id, inviter_person_id,
 auth.uid(), 'active', true, true, true, true, true,
 false, false, false,
 jsonb_build_object('support_role', 'family_supporter', 'family_invitation_id', invitation.id)
 )
 on conflict (book_project_id, supporter_user_id) do update set
 status = 'active', revoked_at = null,
 can_operate_recording = true, can_manage_photos = true,
 can_edit_book_text = true, can_build_book = true,
 meta_json = coalesce(public.project_supporters.meta_json, '{}'::jsonb)
 || jsonb_build_object('support_role', 'family_supporter', 'family_invitation_id', invitation.id),
 updated_at = now();
 end if;

 update public.family_story_invitations
 set recipient_user_id = auth.uid(),
 recipient_project_id = project_row.id,
 claimed_at = coalesce(claimed_at, now()),
 trial_started_at = coalesce(trial_started_at, now()),
 status = case when status in ('ready', 'sent', 'opened', 'accepted') then 'trial_started' else status end
 where id = invitation.id;

 return jsonb_build_object(
 'success', true,
 'invitation_id', invitation.id,
 'project_id', project_row.id,
 'supporter_connected', input_accept_support and invitation.assistance_mode in ('support_requested', 'recipient_chooses'),
 'offer_type', invitation.offer_type
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_book_order_quote(input_book_project_id uuid, input_discount_code text DEFAULT NULL::text, input_standard_extra_copy_count integer DEFAULT 0, input_premium_copy_count integer DEFAULT 0, input_include_gift_package boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  project_row public.book_projects%rowtype;
  base_product public.commerce_products%rowtype;
  premium_product public.commerce_products%rowtype;
  package_product public.commerce_products%rowtype;
  code_row public.discount_codes%rowtype;
  campaign_row public.discount_campaigns%rowtype;
  normalized text := public.normalize_discount_code(input_discount_code);
  base_purchased boolean := false;
  base_amount integer := 0;
  requested_standard integer := coalesce(input_standard_extra_copy_count, 0);
  requested_premium integer := coalesce(input_premium_copy_count, 0);
  ordered_standard integer := 0;
  ordered_premium integer := 0;
  standard_amount integer := 0;
  premium_amount integer := 0;
  package_amount integer := 0;
  discount_amount integer := 0;
  campaign_used integer := 0;
  standard_due_count integer := 0;
  premium_due_count integer := 0;
  pair_quantity integer := 0;
  single_quantity integer := 0;
  additional_quantity integer := 0;
begin
  if requested_standard not between 0 and 30 then
    raise exception 'スタンダード冊子の増刷は1冊から30冊で指定してください' using errcode = '22023';
  end if;
  if requested_premium not between 0 and 30 then
    raise exception 'プレミアム冊子は0冊から30冊で指定してください' using errcode = '22023';
  end if;

  select * into project_row from public.book_projects where id = input_book_project_id;
  if project_row.id is null then raise exception '物語が見つかりません' using errcode = 'P0002'; end if;
  if auth.role() <> 'service_role' and not public.can_manage_book_cover(project_row.id) then
    raise exception 'この物語の注文情報を確認できません' using errcode = '42501';
  end if;

  select * into base_product from public.commerce_products where product_code = 'self_book_v1' and is_active = true;
  select * into premium_product from public.commerce_products where product_code = 'premium_hardcover_v1' and is_active = true;
  select * into package_product from public.commerce_products where product_code = 'gift_package_v1' and is_active = true;
  if base_product.product_code is null or premium_product.product_code is null or package_product.product_code is null then
    raise exception '商品が見つかりません' using errcode = 'P0002';
  end if;

  base_purchased := project_row.access_status in ('paid', 'gifted', 'legacy');
  ordered_standard := coalesce(project_row.ordered_standard_extra_copy_count, 0);
  ordered_premium := coalesce(project_row.ordered_premium_copy_count, 0);
  if requested_standard < ordered_standard or requested_premium < ordered_premium then
    raise exception '購入済みの冊数より少ない冊数には変更できません' using errcode = '22023';
  end if;

  base_amount := case when base_purchased then 0 else base_product.amount_jpy end;
  standard_amount := coalesce(public.standard_reprint_price(requested_standard), 0)
    - coalesce(public.standard_reprint_price(ordered_standard), 0);
  premium_amount := (requested_premium - ordered_premium) * premium_product.amount_jpy;
  package_amount := case
    when input_include_gift_package and not project_row.gift_package_purchased then package_product.amount_jpy
    else 0
  end;
  standard_due_count := requested_standard - ordered_standard;
  premium_due_count := requested_premium - ordered_premium;
  -- The tier is cumulative per production, including separately paid orders.
  -- Keep the existing pair SKU for compatibility with two-copy orders.
  if ordered_standard = 0 and requested_standard >= 2 then
    pair_quantity := 1;
  else
    single_quantity := greatest(least(requested_standard, 2) - least(ordered_standard, 2), 0);
  end if;
  additional_quantity := greatest(requested_standard - 2, 0) - greatest(ordered_standard - 2, 0);

  if normalized <> '' then
    if base_amount = 0 then
      raise exception '基本パッケージは購入済みのため、この注文に割引コードは利用できません' using errcode = '22023';
    end if;
    select c.* into code_row from public.discount_codes c where c.normalized_code = normalized and c.is_active = true;
    if code_row.id is null then raise exception '割引コードを確認できません' using errcode = '22023'; end if;
    select * into campaign_row from public.discount_campaigns where id = code_row.campaign_id;
    if campaign_row.status not in ('active', 'scheduled')
      or (campaign_row.starts_at is not null and campaign_row.starts_at > now())
      or (campaign_row.ends_at is not null and campaign_row.ends_at <= now())
      or (code_row.expires_at is not null and code_row.expires_at <= now()) then
      raise exception 'この割引コードは現在利用できません' using errcode = '22023';
    end if;
    if campaign_row.product_code <> 'self_book_v1' then raise exception 'この商品には利用できない割引コードです' using errcode = '22023'; end if;
    if code_row.max_redemptions is not null and code_row.redemption_count >= code_row.max_redemptions then
      raise exception 'この割引コードは使用済みです' using errcode = '22023';
    end if;
    if campaign_row.max_redemptions is not null then
      select count(*) into campaign_used from public.discount_redemptions
      where campaign_id = campaign_row.id and status in ('pending', 'redeemed');
      if campaign_used >= campaign_row.max_redemptions then raise exception 'このキャンペーンは終了しました' using errcode = '22023'; end if;
    end if;
    if campaign_row.one_per_account and auth.uid() is not null and exists (
      select 1 from public.discount_redemptions
      where campaign_id = campaign_row.id and purchaser_user_id = auth.uid() and status = 'redeemed'
    ) then raise exception 'この割引は1アカウントにつき1回利用できます' using errcode = '22023'; end if;
    discount_amount := case campaign_row.discount_type
      when 'full' then base_amount
      when 'percent' then round(base_amount * campaign_row.discount_value / 100.0)::integer
      else least(base_amount, campaign_row.discount_value::integer)
    end;
  end if;

  return jsonb_build_object(
    'base_product_code', base_product.product_code,
    'base_product_name', base_product.display_name,
    'base_catalog_amount', base_product.amount_jpy,
    'base_already_purchased', base_purchased,
    'includes_base_book', not base_purchased,
    'base_book_amount', base_amount,
    'standard_extra_copy_count', requested_standard,
    'standard_extra_copy_count_already_purchased', ordered_standard,
    'standard_extra_copy_count_due', standard_due_count,
    'standard_reprint_catalog_amount', public.standard_reprint_price(requested_standard),
    'standard_reprint_amount', standard_amount,
    'standard_reprint_pair_quantity', pair_quantity,
    'standard_reprint_single_quantity', single_quantity,
    'standard_reprint_additional_quantity', additional_quantity,
    'premium_copy_count', requested_premium,
    'premium_copy_count_already_purchased', ordered_premium,
    'premium_copy_count_due', premium_due_count,
    'premium_catalog_amount', requested_premium * premium_product.amount_jpy,
    'premium_hardcover_amount', premium_amount,
    'include_premium_hardcover', requested_premium > 0,
    'includes_premium_hardcover', premium_due_count > 0,
    'gift_package_selected', input_include_gift_package,
    'gift_package_already_purchased', project_row.gift_package_purchased,
    'gift_package_amount', package_amount,
    'configuration_total', base_product.amount_jpy + public.standard_reprint_price(requested_standard)
      + (requested_premium * premium_product.amount_jpy)
      + case when input_include_gift_package then package_product.amount_jpy else 0 end,
    'amount_subtotal', base_amount + standard_amount + premium_amount,
    'discount_amount', discount_amount,
    'amount_total', base_amount + standard_amount + premium_amount - discount_amount + package_amount,
    'book_count', 1 + requested_standard + requested_premium,
    'currency', 'jpy',
    'tax_included', true,
    'domestic_shipping_included', true,
    'discount_code_id', code_row.id,
    'discount_code', code_row.code,
    'campaign_id', campaign_row.id,
    'campaign_name', campaign_row.name
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_story_relationship_paused(input_book_project_id uuid, input_relationship_id uuid, input_paused boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare target public.story_relationship_invites%rowtype;
begin
 if not exists (select 1 from public.book_projects bp where bp.id = input_book_project_id and bp.owner_user_id = auth.uid())
 then raise exception 'Project owner access is required'; end if;
 select * into target from public.story_relationship_invites
 where id = input_relationship_id and book_project_id = input_book_project_id and status in ('accepted','paused');
 if target.id is null then return false; end if;

 update public.story_relationship_invites set status = case when input_paused then 'paused' else 'accepted' end, updated_at = now()
 where id = target.id;
 update public.story_share_recipients r set status = case when input_paused then 'revoked' else 'active' end, updated_at = now()
 from public.story_sharing_preferences pref where pref.id = r.sharing_preference_id
 and pref.book_project_id = input_book_project_id and r.recipient_user_id = target.recipient_user_id and r.source = target.invite_type;
 if target.invite_type = 'family' and target.recipient_user_id is not null then
 update public.family_memberships fm set status = case when input_paused then 'paused' else 'active' end, updated_at = now()
 from public.book_projects bp where bp.id = input_book_project_id and fm.family_id = bp.family_id and fm.user_id = target.recipient_user_id;
 end if;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_gift_order(input_claim_token text, input_book_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare gift_row public.gift_orders%rowtype;
declare order_row public.commerce_orders%rowtype;
begin
 if auth.uid() is null then raise exception 'ログインが必要です' using errcode = '42501'; end if;
 select * into gift_row from public.gift_orders where claim_token = input_claim_token for update;
 if gift_row.id is null then raise exception 'ギフトが見つかりません' using errcode = 'P0002'; end if;
 select * into order_row from public.commerce_orders where id = gift_row.commerce_order_id;
 if order_row.status not in ('paid', 'zero_paid') then raise exception 'このギフトはまだ利用できません'; end if;
 if gift_row.claimed_by_user_id is not null and gift_row.claimed_by_user_id <> auth.uid() then
 raise exception 'このギフトは受取済みです' using errcode = '22023';
 end if;
 if not exists (
 select 1 from public.book_projects where id = input_book_project_id and owner_user_id = auth.uid()
 ) then raise exception '物語を確認できません' using errcode = '42501'; end if;

 perform set_config('app.payment_flow', 'on', true);
 update public.book_projects set
 access_status = 'gifted',
 purchaser_user_id = order_row.purchaser_user_id,
 purchased_at = order_row.purchased_at,
 commerce_order_id = order_row.id
 where id = input_book_project_id and owner_user_id = auth.uid();

 update public.commerce_orders set book_project_id = input_book_project_id where id = order_row.id;
 update public.gift_orders set
 claimed_by_user_id = auth.uid(),
 claimed_at = coalesce(claimed_at, now()),
 recipient_project_id = input_book_project_id
 where id = gift_row.id;

 return jsonb_build_object('success', true, 'project_id', input_book_project_id, 'order_id', order_row.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_supporter_invite_resilient(input_invite_id uuid, input_accept boolean)
 RETURNS TABLE(invite_id uuid, book_project_id uuid, response_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 current_user_id uuid := auth.uid();
 current_email text := lower(btrim(coalesce(auth.jwt() ->> 'email', '')));
 target_invite public.project_invites%rowtype;
begin
 if current_user_id is null or current_email = '' then
 raise exception 'Authentication is required';
 end if;

 select pi.* into target_invite
 from public.project_invites pi
 where pi.id = input_invite_id
 and pi.role = 'supporter'
 and lower(btrim(pi.invitee_email)) = current_email;

 if target_invite.id is null then
 raise exception 'The invitation was not found or is not available';
 end if;

 if target_invite.status = 'accepted' and input_accept is true and exists (
 select 1 from public.project_supporters ps
 where ps.book_project_id = target_invite.book_project_id
 and ps.supporter_user_id = current_user_id
 and ps.status = 'active'
 ) then
 return query
 select target_invite.id, target_invite.book_project_id, 'accepted'::text;
 return;
 end if;

 if target_invite.status = 'declined' and input_accept is false then
 return query
 select target_invite.id, target_invite.book_project_id, 'declined'::text;
 return;
 end if;

 if target_invite.status <> 'pending' then
 raise exception 'The invitation was already answered';
 end if;

 return query
 select response.invite_id, response.book_project_id, response.response_status
 from public.respond_to_supporter_invite(input_invite_id, input_accept) response;
end;
$function$

CREATE OR REPLACE FUNCTION public.append_supporter_recording(input_book_project_id uuid, input_user_question_id uuid, input_answer_id uuid, input_transcript_raw text, input_transcript_readable text, input_transcript_essay text, input_selected_style text, input_storage_paths text[], input_duration_seconds numeric DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  actor uuid := auth.uid();
  target_project public.book_projects%rowtype;
  target_question public.user_questions%rowtype;
  target_answer public.answers%rowtype;
  audio_path text;
  part_count integer;
  readable text := coalesce(nullif(input_transcript_readable, ''), input_transcript_raw, '');
begin
  if actor is null or not exists (
    select 1 from public.project_supporters
    where book_project_id = input_book_project_id and supporter_user_id = actor
      and status = 'active' and can_operate_recording = true
  ) then raise exception 'Supporter recording access is not allowed'; end if;

  select * into target_project from public.book_projects
  where id = input_book_project_id and status = 'active';
  if target_project.id is null then raise exception 'Book project was not found'; end if;

  -- Serialize saves for this question, including a retry following a timeout.
  select * into target_question from public.user_questions
  where id = input_user_question_id and book_project_id = input_book_project_id
    and is_active = true for update;
  if target_question.id is null then raise exception 'Question was not found'; end if;

  if input_answer_id is null or coalesce(cardinality(input_storage_paths), 0) <> 1 then
    raise exception 'Exactly one audio segment is required';
  end if;
  audio_path := input_storage_paths[1];
  if audio_path is null or audio_path not in (
    actor::text || '/' || input_book_project_id::text || '/' || input_answer_id::text || '/part-01.mp4',
    actor::text || '/' || input_book_project_id::text || '/' || input_answer_id::text || '/part-01.aac',
    actor::text || '/' || input_book_project_id::text || '/' || input_answer_id::text || '/part-01.webm',
    actor::text || '/' || input_answer_id::text || '/part-01.mp4',
    actor::text || '/' || input_answer_id::text || '/part-01.aac',
    actor::text || '/' || input_answer_id::text || '/part-01.webm'
  ) then raise exception 'Forbidden audio path'; end if;
  if not exists (select 1 from storage.objects where bucket_id = 'audio' and name = audio_path) then
    raise exception 'Uploaded audio was not found';
  end if;
  if input_duration_seconds is null or input_duration_seconds < 0 or input_duration_seconds > 86400 then
    raise exception 'Invalid duration';
  end if;

  select * into target_answer from public.answers
  where book_project_id = input_book_project_id and user_question_id = input_user_question_id
  order by created_at desc limit 1 for update;
  if exists (select 1 from public.media_assets where storage_path = audio_path and asset_type = 'audio') then
    if exists (select 1 from public.media_assets where answer_id = target_answer.id
      and storage_path = audio_path and asset_type = 'audio') then
      return target_answer.id;
    end if;
    raise exception 'Audio segment already belongs to another answer';
  end if;

  if target_answer.id is null then
    insert into public.answers (
      id, user_id, book_project_id, speaker_person_id, subject_person_id,
      user_question_id, question_id, sequence_order, transcript_raw,
      transcript_clean, transcript_readable, transcript_essay, transcript_edited,
      selected_style, ai_mirror, snippet, meta_json
    ) values (
      input_answer_id, target_project.owner_user_id, target_project.id,
      target_project.subject_person_id, target_project.subject_person_id,
      target_question.id, target_question.question_id, target_question.sequence_order,
      coalesce(input_transcript_raw, ''), readable, readable, nullif(input_transcript_essay, ''), readable,
      'readable', 'ご家族と残した声が、ひとつの物語になりました', '',
      jsonb_build_object('recorded_with_supporter', true, 'supporter_user_id', actor,
        'duration_seconds', input_duration_seconds)
    ) returning * into target_answer;
  else
    update public.answers set
      transcript_raw = concat_ws(E'\n\n', nullif(transcript_raw, ''), nullif(input_transcript_raw, '')),
      transcript_clean = concat_ws(E'\n\n', nullif(transcript_clean, ''), nullif(readable, '')),
      transcript_readable = concat_ws(E'\n\n', nullif(transcript_readable, ''), nullif(readable, '')),
      transcript_essay = concat_ws(E'\n\n', nullif(transcript_essay, ''), nullif(input_transcript_essay, '')),
      transcript_edited = concat_ws(E'\n\n', coalesce(nullif(transcript_edited, ''), nullif(transcript_readable, '')), nullif(readable, '')),
      selected_style = 'readable',
      meta_json = coalesce(meta_json, '{}'::jsonb) || jsonb_build_object(
        'recorded_with_supporter', true, 'supporter_user_id', actor,
        'duration_seconds', coalesce((meta_json->>'duration_seconds')::numeric, 0) + input_duration_seconds
      )
    where id = target_answer.id;
  end if;

  select count(*) + 1 into part_count from public.media_assets
  where answer_id = target_answer.id and asset_type = 'audio';
  insert into public.media_assets (
    answer_id, user_id, family_id, book_project_id, person_id, asset_type, storage_path, meta_json
  ) values (
    target_answer.id, target_project.owner_user_id, target_project.family_id,
    target_project.id, target_project.subject_person_id, 'audio', audio_path,
    jsonb_build_object('part', part_count, 'total_parts', part_count,
      'recorded_with_supporter', true, 'supporter_user_id', actor,
      'segment_id', input_answer_id, 'duration_seconds', input_duration_seconds)
  );
  update public.media_assets set meta_json = coalesce(meta_json, '{}'::jsonb) || jsonb_build_object('total_parts', part_count)
  where answer_id = target_answer.id and asset_type = 'audio';
  update public.user_questions set status = 'answered', answered_at = coalesce(answered_at, now())
  where id = target_question.id;
  return target_answer.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_product_price(input_product_code text, input_amount_jpy integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare product_row public.commerce_products%rowtype;
begin
 if not public.is_admin_sales_mode_active() then raise exception '販売管理モードが必要です' using errcode = '42501'; end if;
 if input_amount_jpy < 0 then raise exception '価格が不正です'; end if;
 -- Keep the Stripe Product stable so product-scoped coupons stay valid; only a new Price is required.
 update public.commerce_products set amount_jpy = input_amount_jpy, stripe_price_id = null
 where product_code = input_product_code returning * into product_row;
 insert into public.admin_audit_logs(admin_user_id, action, entity_type, metadata)
 values (auth.uid(), 'change_product_price', 'commerce_product', jsonb_build_object('product_code', input_product_code, 'amount_jpy', input_amount_jpy));
 return to_jsonb(product_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_sales_mode_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare expiry timestamptz; declare minutes integer := 15; declare role_value text;
begin
 select role into role_value from public.admin_users where user_id = auth.uid() and is_active;
 if role_value is null then raise exception 'Admin access required' using errcode = '42501'; end if;
 select coalesce(integer_value, 15) into minutes from public.commerce_settings where setting_key = 'sales_mode_minutes';
 select expires_at into expiry from public.admin_sales_mode_sessions where admin_user_id = auth.uid() and expires_at > now();
 return jsonb_build_object('active', expiry is not null and role_value = 'owner', 'expires_at', expiry, 'duration_minutes', minutes, 'can_start', role_value = 'owner');
end;
$function$

CREATE OR REPLACE FUNCTION public.start_admin_sales_mode()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare minutes integer := 15; declare expiry timestamptz; declare last_auth timestamptz;
begin
 if not exists (select 1 from public.admin_users where user_id = auth.uid() and is_active and role = 'owner') then
 raise exception 'Owner access required' using errcode = '42501';
 end if;
 select last_sign_in_at into last_auth from auth.users where id = auth.uid();
 if last_auth is null or last_auth < now() - interval '5 minutes' then raise exception 'Recent reauthentication required' using errcode = '42501'; end if;
 select coalesce(integer_value, 15) into minutes from public.commerce_settings where setting_key = 'sales_mode_minutes';
 expiry := now() + make_interval(mins => minutes);
 insert into public.admin_sales_mode_sessions(admin_user_id, started_at, expires_at)
 values (auth.uid(), now(), expiry) on conflict (admin_user_id) do update set started_at = now(), expires_at = excluded.expires_at;
 insert into public.admin_audit_logs(admin_user_id, action, entity_type, metadata)
 values (auth.uid(), 'start_sales_mode', 'admin_session', jsonb_build_object('expires_at', expiry));
 return jsonb_build_object('active', true, 'expires_at', expiry, 'duration_minutes', minutes);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_discount_campaign(input_campaign jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  campaign_row public.discount_campaigns%rowtype;
  requested_scope text := coalesce(nullif(input_campaign ->> 'discount_scope', ''), 'base_product');
  requested_type text := input_campaign ->> 'campaign_type';
  requested_discount_type text := input_campaign ->> 'discount_type';
  requested_ends_at timestamptz := nullif(input_campaign ->> 'ends_at', '')::timestamptz;
  requested_one_per_account boolean := coalesce((input_campaign ->> 'one_per_account')::boolean, false);
begin
  if public.is_admin_sales_mode_active() is not true then
    raise exception '販売管理モードが必要です' using errcode = '42501';
  end if;

  if requested_scope = 'entire_order' then
    if requested_type <> 'internal_test' or requested_discount_type <> 'full' then
      raise exception '全項目を無料にできるのは内部テスト用の全額割引だけです' using errcode = '22023';
    end if;
    if requested_ends_at is null or requested_ends_at <= now() then
      raise exception '全項目無料の内部テストには有効期限が必要です' using errcode = '22023';
    end if;
  end if;

  if nullif(input_campaign ->> 'id', '') is null then
    insert into public.discount_campaigns(
      name, campaign_type, product_code, discount_type, discount_value,
      discount_scope, starts_at, ends_at, max_redemptions, one_per_account,
      status, partner_name, partner_reference, created_by
    ) values (
      btrim(input_campaign ->> 'name'), requested_type,
      coalesce(input_campaign ->> 'product_code', 'self_book_v1'),
      requested_discount_type, (input_campaign ->> 'discount_value')::numeric,
      requested_scope, nullif(input_campaign ->> 'starts_at', '')::timestamptz,
      requested_ends_at, nullif(input_campaign ->> 'max_redemptions', '')::integer,
      requested_one_per_account, coalesce(input_campaign ->> 'status', 'draft'),
      nullif(input_campaign ->> 'partner_name', ''),
      nullif(input_campaign ->> 'partner_reference', ''), auth.uid()
    ) returning * into campaign_row;
  else
    update public.discount_campaigns set
      name = btrim(input_campaign ->> 'name'),
      campaign_type = requested_type,
      discount_type = requested_discount_type,
      discount_value = (input_campaign ->> 'discount_value')::numeric,
      discount_scope = requested_scope,
      starts_at = nullif(input_campaign ->> 'starts_at', '')::timestamptz,
      ends_at = requested_ends_at,
      max_redemptions = nullif(input_campaign ->> 'max_redemptions', '')::integer,
      one_per_account = requested_one_per_account,
      status = coalesce(input_campaign ->> 'status', status),
      partner_name = nullif(input_campaign ->> 'partner_name', ''),
      partner_reference = nullif(input_campaign ->> 'partner_reference', ''),
      stripe_coupon_id = null,
      stripe_mode = null
    where id = (input_campaign ->> 'id')::uuid
    returning * into campaign_row;
  end if;

  return to_jsonb(campaign_row);
end;
$function$

