CREATE OR REPLACE FUNCTION public.create_family_story_invitation(input_recipient_name text, input_recipient_email text, input_relationship_label text, input_assistance_mode text, input_offer_type text, input_delivery_method text, input_message_template text, input_personal_message text DEFAULT NULL::text, input_shipping_address jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 result public.family_story_invitations%rowtype;
 normalized_name text := nullif(btrim(coalesce(input_recipient_name, '')), '');
 normalized_email text := nullif(lower(btrim(coalesce(input_recipient_email, ''))), '');
 next_status text;
 next_email_status text;
 next_package_status text;
begin
 if auth.uid() is null then
 raise exception 'ログインが必要です' using errcode = '42501';
 end if;
 if normalized_name is null or char_length(normalized_name) > 80 then
 raise exception '贈る相手のお名前を入力してください' using errcode = '22023';
 end if;
 if coalesce(input_relationship_label, '') not in ('parent', 'grandparent', 'spouse', 'sibling', 'child', 'grandchild', 'other') then
 raise exception '続柄を確認してください' using errcode = '22023';
 end if;
 if coalesce(input_assistance_mode, '') not in ('recipient_led', 'support_requested', 'recipient_chooses') then
 raise exception 'お手伝い方法を確認してください' using errcode = '22023';
 end if;
 if coalesce(input_offer_type, '') not in ('referral', 'trial_gift', 'full_gift') then
 raise exception '招待方法を確認してください' using errcode = '22023';
 end if;
 if coalesce(input_delivery_method, '') not in ('email', 'package') then
 raise exception '届け方を確認してください' using errcode = '22023';
 end if;
 if input_offer_type = 'referral' and input_delivery_method <> 'email' then
 raise exception '紹介はメールでお届けします' using errcode = '22023';
 end if;
 if input_delivery_method = 'email' and normalized_email is null then
 raise exception 'メールアドレスを入力してください' using errcode = '22023';
 end if;
 if input_delivery_method = 'package' and not (
 coalesce(input_shipping_address ->> 'postal_code', '') <> '' and
 coalesce(input_shipping_address ->> 'prefecture', '') <> '' and
 coalesce(input_shipping_address ->> 'city', '') <> '' and
 coalesce(input_shipping_address ->> 'line1', '') <> ''
 ) then
 raise exception 'ギフトパッケージのお届け先を入力してください' using errcode = '22023';
 end if;

 next_status := case
 when input_offer_type = 'full_gift' then 'awaiting_payment'
 when input_offer_type = 'trial_gift' and input_delivery_method = 'package' then 'awaiting_payment'
 else 'ready'
 end;
 next_email_status := case when input_delivery_method = 'email' and next_status = 'ready' then 'pending' else 'not_requested' end;
 next_package_status := case
 when input_delivery_method <> 'package' then 'not_requested'
 when next_status = 'awaiting_payment' then 'awaiting_payment'
 else 'pending'
 end;

 insert into public.family_story_invitations (
 inviter_user_id, recipient_name, recipient_email, relationship_label,
 assistance_mode, offer_type, delivery_method, message_template,
 personal_message, shipping_address, supporter_requested,
 progress_sharing, status, email_delivery_status, package_status,
 claim_token, claim_code
 ) values (
 auth.uid(), normalized_name, normalized_email, input_relationship_label,
 input_assistance_mode, input_offer_type, input_delivery_method,
 coalesce(nullif(btrim(input_message_template), ''), 'hear_your_story'),
 nullif(btrim(coalesce(input_personal_message, '')), ''),
 coalesce(input_shipping_address, '{}'::jsonb),
 input_assistance_mode = 'support_requested',
 case when input_offer_type in ('trial_gift', 'full_gift') then 'milestones' else 'none' end,
 next_status, next_email_status, next_package_status,
 replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
 upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))
 ) returning * into result;

 return to_jsonb(result);
end;
$function$

CREATE OR REPLACE FUNCTION public.book_cover_project_id_from_path(input_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
 project_text text;
begin
 if input_path !~ '^book-covers/[0-9a-fA-F-]{36}/' then
 return null;
 end if;

 project_text := split_part(input_path, '/', 2);
 return project_text::uuid;
exception when others then
 return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_organization_mode_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 admin_role text;
 mode_expires_at timestamptz;
 duration_minutes integer;
begin
 select role
 into admin_role
 from public.admin_users
 where user_id = auth.uid()
 and is_active = true;

 if auth.uid() is null or admin_role is null then
 raise exception 'Admin access required' using errcode = '42501';
 end if;

 select integer_value
 into duration_minutes
 from public.admin_operation_settings
 where setting_key = 'organization_mode_minutes';

 select expires_at
 into mode_expires_at
 from public.admin_organization_mode_sessions
 where admin_user_id = auth.uid()
 and expires_at > now();

 return jsonb_build_object(
 'role', admin_role,
 'can_start', admin_role = 'owner',
 'active', mode_expires_at is not null and admin_role = 'owner',
 'expires_at', mode_expires_at,
 'duration_minutes', coalesce(duration_minutes, 15)
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.start_admin_organization_mode()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 last_authenticated_at timestamptz;
 duration_minutes integer;
 mode_expires_at timestamptz;
begin
 if auth.uid() is null or not exists (
 select 1
 from public.admin_users
 where user_id = auth.uid()
 and is_active = true
 and role = 'owner'
 ) then
 raise exception 'Owner access required' using errcode = '42501';
 end if;

 select last_sign_in_at
 into last_authenticated_at
 from auth.users
 where id = auth.uid();

 if last_authenticated_at is null
 or last_authenticated_at < now() - interval '5 minutes' then
 raise exception 'Recent reauthentication required' using errcode = '42501';
 end if;

 select integer_value
 into duration_minutes
 from public.admin_operation_settings
 where setting_key = 'organization_mode_minutes';

 duration_minutes := coalesce(duration_minutes, 15);
 mode_expires_at := now() + make_interval(mins => duration_minutes);

 insert into public.admin_organization_mode_sessions(
 admin_user_id,
 started_at,
 expires_at
 )
 values (auth.uid(), now(), mode_expires_at)
 on conflict (admin_user_id) do update
 set started_at = excluded.started_at,
 expires_at = excluded.expires_at;

 insert into public.admin_audit_logs(
 admin_user_id,
 action,
 entity_type,
 metadata
 )
 values (
 auth.uid(),
 'start_organization_mode',
 'admin_session',
 jsonb_build_object(
 'duration_minutes', duration_minutes,
 'expires_at', mode_expires_at
 )
 );

 return jsonb_build_object(
 'active', true,
 'expires_at', mode_expires_at,
 'duration_minutes', duration_minutes
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.end_admin_organization_mode()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 removed_count integer;
begin
 if auth.uid() is null or not public.is_tateyoko_admin() then
 raise exception 'Admin access required' using errcode = '42501';
 end if;

 delete from public.admin_organization_mode_sessions
 where admin_user_id = auth.uid();
 get diagnostics removed_count = row_count;

 if removed_count > 0 then
 insert into public.admin_audit_logs(
 admin_user_id,
 action,
 entity_type
 )
 values (auth.uid(), 'end_organization_mode', 'admin_session');
 end if;

 return jsonb_build_object('active', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.move_admin_entity_to_trash(input_entity_type text, input_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 normalized_type text := lower(btrim(coalesce(input_entity_type, '')));
 entity_snapshot jsonb;
 inserted_id uuid;
begin
 if auth.uid() is null or not exists (
 select 1
 from public.admin_users
 where user_id = auth.uid()
 and is_active = true
 and role = 'owner'
 ) or not public.is_admin_organization_mode_active() then
 raise exception 'Active owner organization mode required' using errcode = '42501';
 end if;

 if normalized_type <> 'book_project' then
 raise exception 'Account retirement must use the account lifecycle service' using errcode = '22023';
 end if;

 select jsonb_build_object(
 'title', bp.title,
 'display_name', coalesce(
 nullif(btrim(concat_ws(' ', nullif(to_jsonb(subject) ->> 'family_name', ''), nullif(to_jsonb(subject) ->> 'given_name', ''))), ''),
 nullif(to_jsonb(subject) ->> 'preferred_name', ''),
 nullif(to_jsonb(subject) ->> 'display_name', ''),
 bp.title,
 '名称未登録'
 ),
 'owner_user_id', bp.owner_user_id,
 'owner_email', owner.email,
 'subject_person_id', bp.subject_person_id,
 'access_status', bp.access_status,
 'purchased_at', bp.purchased_at
 )
 into entity_snapshot
 from public.book_projects bp
 left join auth.users owner on owner.id = bp.owner_user_id
 left join public.persons subject on subject.id = bp.subject_person_id
 where bp.id = input_entity_id;

 if entity_snapshot is null then
 raise exception 'Trash target not found' using errcode = 'P0002';
 end if;

 insert into public.admin_trash_entries(
 entity_type,
 entity_id,
 lifecycle_status,
 trashed_by_admin_user_id,
 snapshot
 )
 values (normalized_type, input_entity_id, 'hidden', auth.uid(), entity_snapshot)
 on conflict (entity_type, entity_id) do nothing
 returning id into inserted_id;

 if inserted_id is not null then
 insert into public.admin_audit_logs(
 admin_user_id,
 action,
 entity_type,
 entity_id,
 metadata
 )
 values (
 auth.uid(),
 'hide_entity',
 normalized_type,
 input_entity_id,
 jsonb_build_object('snapshot', entity_snapshot)
 );
 end if;

 return jsonb_build_object(
 'success', true,
 'entity_type', normalized_type,
 'entity_id', input_entity_id,
 'already_hidden', inserted_id is null
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_trash_index()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 result jsonb;
 can_view_hidden_details boolean;
begin
 if auth.uid() is null or not public.is_tateyoko_admin() then
 raise exception 'Admin access required' using errcode = '42501';
 end if;

 can_view_hidden_details := public.is_admin_organization_mode_active();

 select coalesce(jsonb_agg(jsonb_build_object(
 'entity_type', trash.entity_type,
 'entity_id', trash.entity_id,
 'lifecycle_status', trash.lifecycle_status,
 'trash_origin', trash.trash_origin,
 'source_account_id', trash.source_account_id,
 'snapshot', case
 when can_view_hidden_details then trash.snapshot
 when trash.entity_type = 'book_project' then jsonb_build_object(
 'owner_user_id', trash.snapshot -> 'owner_user_id',
 'access_status', trash.snapshot -> 'access_status'
 )
 else '{}'::jsonb
 end,
 'trashed_at', trash.trashed_at
 ) order by trash.trashed_at desc), '[]'::jsonb)
 into result
 from public.admin_trash_entries trash;

 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_book_order_quote(input_book_project_id uuid, input_discount_code text DEFAULT NULL::text, input_include_premium_hardcover boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 project_row public.book_projects%rowtype;
 base_product public.commerce_products%rowtype;
 premium_product public.commerce_products%rowtype;
 code_row public.discount_codes%rowtype;
 campaign_row public.discount_campaigns%rowtype;
 normalized text := public.normalize_discount_code(input_discount_code);
 base_purchased boolean := false;
 premium_purchased boolean := false;
 include_premium boolean := false;
 base_amount integer := 0;
 premium_amount integer := 0;
 discount_amount integer := 0;
 campaign_used integer := 0;
begin
 select * into project_row from public.book_projects where id = input_book_project_id;
 if project_row.id is null then
 raise exception '物語が見つかりません' using errcode = 'P0002';
 end if;
 if auth.role() <> 'service_role' and not public.can_manage_book_cover(project_row.id) then
 raise exception 'この物語の注文情報を確認できません' using errcode = '42501';
 end if;

 select * into base_product from public.commerce_products
 where product_code = 'self_book_v1' and is_active = true;
 select * into premium_product from public.commerce_products
 where product_code = 'premium_hardcover_v1' and is_active = true;
 if base_product.product_code is null or premium_product.product_code is null then
 raise exception '商品が見つかりません' using errcode = 'P0002';
 end if;

 base_purchased := project_row.access_status in ('paid', 'gifted', 'legacy');
 premium_purchased := project_row.premium_hardcover_status = 'paid'
 or project_row.premium_hardcover_purchased_at is not null;
 include_premium := input_include_premium_hardcover or premium_purchased;
 base_amount := case when base_purchased then 0 else base_product.amount_jpy end;
 premium_amount := case when include_premium and not premium_purchased then premium_product.amount_jpy else 0 end;

 if normalized <> '' then
 if base_amount = 0 then
 raise exception '基本セットは購入済みのため、この注文に割引コードは利用できません' using errcode = '22023';
 end if;
 select c.* into code_row from public.discount_codes c
 where c.normalized_code = normalized and c.is_active = true;
 if code_row.id is null then raise exception '割引コードを確認できません' using errcode = '22023'; end if;
 select * into campaign_row from public.discount_campaigns where id = code_row.campaign_id;
 if campaign_row.status not in ('active', 'scheduled')
 or (campaign_row.starts_at is not null and campaign_row.starts_at > now())
 or (campaign_row.ends_at is not null and campaign_row.ends_at <= now())
 or (code_row.expires_at is not null and code_row.expires_at <= now()) then
 raise exception 'この割引コードは現在利用できません' using errcode = '22023';
 end if;
 if campaign_row.product_code <> 'self_book_v1' then
 raise exception 'この商品には利用できない割引コードです' using errcode = '22023';
 end if;
 if code_row.max_redemptions is not null and code_row.redemption_count >= code_row.max_redemptions then
 raise exception 'この割引コードは使用済みです' using errcode = '22023';
 end if;
 if campaign_row.max_redemptions is not null then
 select count(*) into campaign_used from public.discount_redemptions
 where campaign_id = campaign_row.id and status in ('pending', 'redeemed');
 if campaign_used >= campaign_row.max_redemptions then
 raise exception 'このキャンペーンは終了しました' using errcode = '22023';
 end if;
 end if;
 if campaign_row.one_per_account and auth.uid() is not null and exists (
 select 1 from public.discount_redemptions
 where campaign_id = campaign_row.id and purchaser_user_id = auth.uid() and status = 'redeemed'
 ) then
 raise exception 'この割引は1アカウントにつき1回利用できます' using errcode = '22023';
 end if;
 discount_amount := case campaign_row.discount_type
 when 'full' then base_amount
 when 'percent' then round(base_amount * campaign_row.discount_value / 100.0)::integer
 else least(base_amount, campaign_row.discount_value::integer)
 end;
 end if;

 return jsonb_build_object(
 'base_product_code', base_product.product_code,
 'base_product_name', base_product.display_name,
 'premium_product_code', premium_product.product_code,
 'premium_product_name', premium_product.display_name,
 'base_already_purchased', base_purchased,
 'premium_already_purchased', premium_purchased,
 'include_premium_hardcover', include_premium,
 'includes_base_book', not base_purchased,
 'base_book_amount', base_amount,
 'premium_hardcover_amount', premium_amount,
 'amount_subtotal', base_amount + premium_amount,
 'discount_amount', discount_amount,
 'amount_total', base_amount + premium_amount - discount_amount,
 'book_count', case when include_premium then 2 else 1 end,
 'currency', 'jpy',
 'tax_included', true,
 'domestic_shipping_included', true,
 'discount_code_id', code_row.id,
 'discount_code', code_row.code,
 'campaign_id', campaign_row.id,
 'campaign_name', campaign_row.name
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_admin_entity_from_trash(input_entity_type text, input_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 normalized_type text := lower(btrim(coalesce(input_entity_type, '')));
 target_entry public.admin_trash_entries%rowtype;
begin
 if auth.uid() is null or not exists (
 select 1
 from public.admin_users
 where user_id = auth.uid()
 and is_active = true
 and role = 'owner'
 ) or not public.is_admin_organization_mode_active() then
 raise exception 'Active owner organization mode required' using errcode = '42501';
 end if;

 select *
 into target_entry
 from public.admin_trash_entries
 where entity_type = normalized_type
 and entity_id = input_entity_id;

 if target_entry.id is null then
 raise exception 'Hidden target not found' using errcode = 'P0002';
 end if;

 if normalized_type = 'account' and target_entry.lifecycle_status = 'retired' then
 raise exception 'Retired accounts must use the account lifecycle service' using errcode = '22023';
 end if;

 if normalized_type = 'book_project' and target_entry.trash_origin = 'account_retirement' then
 raise exception 'Projects hidden by account retirement must be restored with the account' using errcode = '22023';
 end if;

 delete from public.admin_trash_entries
 where id = target_entry.id;

 insert into public.admin_audit_logs(
 admin_user_id,
 action,
 entity_type,
 entity_id,
 metadata
 )
 values (
 auth.uid(),
 'restore_hidden_entity',
 normalized_type,
 input_entity_id,
 jsonb_build_object('snapshot', target_entry.snapshot)
 );

 return jsonb_build_object(
 'success', true,
 'entity_type', normalized_type,
 'entity_id', input_entity_id
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.project_v2_gift_guarantee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; paid_at timestamptz;
begin
 select * into c from experience_contracts where order_id=new.commerce_order_id;
 if c.order_id is null then return new; end if;
 new.guarantee_days := c.guarantee_days;
 select purchased_at into paid_at from commerce_orders where id=c.order_id;
 new.guarantee_starts_at := coalesce(c.payment_confirmed_at,paid_at);
 new.guarantee_expires_at := new.guarantee_starts_at + interval '45 days';
 new.guarantee_status := case when c.refund_confirmed_at is not null then 'refunded'
   when c.main_experience_started_at is not null then 'continued'
   when new.guarantee_starts_at is null then 'not_started' else 'eligible' end;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.bind_claimed_v2_gift()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
 if new.claimed_at is not null and new.recipient_project_id is not null and exists(
   select 1 from experience_contracts where order_id=new.commerce_order_id and payment_confirmed_at is not null
 ) then perform public.bind_gift_experience_contract(new.commerce_order_id); end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.guard_experience_content_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare pid uuid; q public.user_questions%rowtype; c public.experience_contracts%rowtype;
begin
 pid := (to_jsonb(new)->>'book_project_id')::uuid;
 if pid is null and tg_table_name='media_assets' then select book_project_id into pid from answers where id=new.answer_id; end if;
 perform 1 from experience_contracts where book_project_id=pid for update;
 if not public.experience_data_allowed(pid,true) then raise exception 'Production access suspended' using errcode='42501'; end if;
 select * into c from experience_contracts where book_project_id=pid and payment_confirmed_at is not null and refund_confirmed_at is null;
 if c.order_id is not null and c.production_started_at is null then
   if tg_table_name='answers' then select * into q from user_questions where id=new.user_question_id;
   elsif tg_table_name='media_assets' then select uq.* into q from user_questions uq join answers a on a.user_question_id=uq.id where a.id=new.answer_id;
   else raise exception 'Start the paid introduction first'; end if;
   if q.id is null or coalesce(q.meta_json->>'onboarding_group','')<>'trial_experience' then raise exception 'Only the free trial is available before paid introduction'; end if;
 end if;
 if tg_table_name='answers' and exists(select 1 from experience_contracts where book_project_id=pid and payment_confirmed_at is not null) then
   select * into q from user_questions where id=new.user_question_id;
   if q.id is null or q.book_project_id is distinct from pid then raise exception 'Question does not belong to project'; end if;
   if coalesce(q.meta_json->>'onboarding_group','')<>'trial_experience' and (q.sequence_order is null or q.sequence_order>4)
     and not exists(select 1 from experience_contracts where book_project_id=pid and main_experience_started_at is not null and refund_confirmed_at is null) then
     raise exception 'Explicit main experience start required' using errcode='42501';
   end if;
 end if;
 return new;
end; $function$

