CREATE OR REPLACE FUNCTION public.expire_commerce_order(input_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare order_row public.commerce_orders%rowtype;
begin
 select * into order_row from public.commerce_orders where id = input_order_id;
 update public.commerce_orders set status = 'expired'
 where id = input_order_id and status = 'checkout_pending';
 update public.discount_redemptions set status = 'released'
 where commerce_order_id = input_order_id and status = 'pending';
 if order_row.includes_base_book then
 update public.book_projects set access_status = 'trial'
 where commerce_order_id = input_order_id and access_status = 'checkout_pending';
 end if;
 if order_row.includes_premium_hardcover then
 update public.book_projects set premium_hardcover_status = 'selected'
 where id = order_row.book_project_id and premium_hardcover_status = 'checkout_pending';
 end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_commerce_order(input_order_id uuid, input_checkout_session_id text, input_customer_id text, input_payment_intent_id text, input_payment_status text, input_amount_total integer, input_stripe_mode text, input_purchased_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 order_row public.commerce_orders%rowtype;
 gift_row public.gift_orders%rowtype;
 redemption_row public.discount_redemptions%rowtype;
 next_status text;
 configured_guarantee_days integer := 40;
begin
 select * into order_row from public.commerce_orders where id = input_order_id for update;
 if order_row.id is null then raise exception 'Order not found' using errcode = 'P0002'; end if;
 if input_payment_status not in ('paid', 'no_payment_required') then raise exception 'Payment is not complete'; end if;
 if input_amount_total is distinct from order_row.amount_total then raise exception 'Payment total does not match order'; end if;
 next_status := case when input_payment_status = 'no_payment_required' or order_row.amount_total = 0 then 'zero_paid' else 'paid' end;

 update public.commerce_orders set
 status = next_status,
 stripe_checkout_session_id = input_checkout_session_id,
 stripe_customer_id = nullif(input_customer_id, ''),
 stripe_payment_intent_id = nullif(input_payment_intent_id, ''),
 stripe_mode = input_stripe_mode,
 purchased_at = coalesce(purchased_at, input_purchased_at, now())
 where id = order_row.id returning * into order_row;

 select * into redemption_row from public.discount_redemptions where commerce_order_id = order_row.id for update;
 if redemption_row.id is not null and redemption_row.status = 'pending' then
 update public.discount_redemptions set status = 'redeemed', redeemed_at = now() where id = redemption_row.id;
 update public.discount_codes set redemption_count = redemption_count + 1, last_redeemed_at = now()
 where id = redemption_row.discount_code_id;
 end if;

 if order_row.order_type = 'self' and order_row.book_project_id is not null then
 perform set_config('app.payment_flow', 'on', true);
 update public.book_projects set
 access_status = case when order_row.includes_base_book then 'paid' else access_status end,
 purchased_at = case when order_row.includes_base_book then coalesce(purchased_at, order_row.purchased_at) else purchased_at end,
 purchaser_user_id = case when order_row.includes_base_book then order_row.purchaser_user_id else purchaser_user_id end,
 stripe_checkout_session_id = case when order_row.includes_base_book then input_checkout_session_id else stripe_checkout_session_id end,
 stripe_customer_id = case when order_row.includes_base_book then nullif(input_customer_id, '') else stripe_customer_id end,
 stripe_payment_intent_id = case when order_row.includes_base_book then nullif(input_payment_intent_id, '') else stripe_payment_intent_id end,
 commerce_order_id = case when order_row.includes_base_book then order_row.id else commerce_order_id end,
 ordered_standard_extra_copy_count = greatest(ordered_standard_extra_copy_count, order_row.requested_standard_extra_copy_count),
 ordered_premium_copy_count = greatest(ordered_premium_copy_count, order_row.requested_premium_copy_count),
 gift_package_purchased = gift_package_purchased or order_row.gift_package_selected,
 premium_hardcover_status = case when order_row.requested_premium_copy_count > 0 then 'paid' else premium_hardcover_status end,
 premium_hardcover_purchased_at = case
 when order_row.requested_premium_copy_count > 0 then coalesce(premium_hardcover_purchased_at, order_row.purchased_at)
 else premium_hardcover_purchased_at
 end,
 premium_hardcover_order_id = case
 when order_row.premium_copy_count > 0 then order_row.id else premium_hardcover_order_id
 end
 where id = order_row.book_project_id;
 else
 select coalesce(integer_value, 40) into configured_guarantee_days
 from public.commerce_settings where setting_key = 'gift_guarantee_days';
 select * into gift_row from public.gift_orders where commerce_order_id = order_row.id;
 if gift_row.id is not null and not gift_row.package_selected then
 update public.gift_orders set
 guarantee_starts_at = coalesce(guarantee_starts_at, order_row.purchased_at),
 guarantee_expires_at = coalesce(guarantee_expires_at, order_row.purchased_at + make_interval(days => configured_guarantee_days)),
 guarantee_status = case when guarantee_status = 'not_started' then 'eligible' else guarantee_status end
 where id = gift_row.id returning * into gift_row;
 end if;
 end if;

 return jsonb_build_object('order', to_jsonb(order_row), 'gift', case when gift_row.id is null then null else to_jsonb(gift_row) end);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_book_commerce_order(input_purchaser_user_id uuid, input_book_project_id uuid, input_discount_code text, input_include_premium_hardcover boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 quote jsonb;
 code_row public.discount_codes%rowtype;
 campaign_row public.discount_campaigns%rowtype;
 order_row public.commerce_orders%rowtype;
 reservation_minutes integer := 60;
 used_count integer;
 primary_product_code text;
 snapshot jsonb := '{}'::jsonb;
begin
 if input_purchaser_user_id is null then raise exception '購入者が必要です'; end if;
 if not exists (
 select 1 from public.book_projects
 where id = input_book_project_id and owner_user_id = input_purchaser_user_id
 ) then raise exception 'この物語の購入手続きを開始できません' using errcode = '42501'; end if;

 select coalesce(integer_value, 60) into reservation_minutes
 from public.commerce_settings where setting_key = 'checkout_reservation_minutes';
 update public.commerce_orders set status = 'expired'
 where status = 'checkout_pending' and created_at < now() - make_interval(mins => reservation_minutes);
 update public.discount_redemptions r set status = 'released'
 where status = 'pending' and exists (
 select 1 from public.commerce_orders o where o.id = r.commerce_order_id and o.status = 'expired'
 );

 quote := public.get_book_order_quote(input_book_project_id, input_discount_code, input_include_premium_hardcover);
 if not coalesce((quote ->> 'includes_base_book')::boolean, false)
 and coalesce((quote ->> 'premium_hardcover_amount')::integer, 0) = 0 then
 raise exception '追加のお支払いはありません' using errcode = '22023';
 end if;

 if quote ->> 'discount_code_id' is not null then
 select * into code_row from public.discount_codes
 where id = (quote ->> 'discount_code_id')::uuid for update;
 select * into campaign_row from public.discount_campaigns where id = code_row.campaign_id for update;
 select count(*) into used_count from public.discount_redemptions
 where discount_code_id = code_row.id and status in ('pending', 'redeemed');
 if code_row.max_redemptions is not null and used_count >= code_row.max_redemptions then
 raise exception 'この割引コードは使用中または使用済みです' using errcode = '22023';
 end if;
 if campaign_row.one_per_account and exists (
 select 1 from public.discount_redemptions
 where campaign_id = code_row.campaign_id
 and purchaser_user_id = input_purchaser_user_id
 and status in ('pending', 'redeemed')
 ) then
 raise exception 'この割引は1アカウントにつき1回利用できます' using errcode = '22023';
 end if;
 end if;

 select coalesce(to_jsonb(s), '{}'::jsonb) into snapshot
 from public.book_cover_settings s where s.book_project_id = input_book_project_id;
 primary_product_code := case
 when coalesce((quote ->> 'includes_base_book')::boolean, false) then 'self_book_v1'
 else 'premium_hardcover_v1'
 end;

 insert into public.commerce_orders(
 purchaser_user_id, book_project_id, order_type, product_code,
 amount_subtotal, gift_package_amount, discount_amount, amount_total,
 currency, discount_code_id, status,
 includes_base_book, includes_premium_hardcover,
 base_book_amount, premium_hardcover_amount, design_snapshot
 ) values (
 input_purchaser_user_id, input_book_project_id, 'self', primary_product_code,
 (quote ->> 'amount_subtotal')::integer, 0,
 (quote ->> 'discount_amount')::integer, (quote ->> 'amount_total')::integer,
 'jpy', nullif(quote ->> 'discount_code_id', '')::uuid, 'checkout_pending',
 coalesce((quote ->> 'includes_base_book')::boolean, false),
 coalesce((quote ->> 'include_premium_hardcover')::boolean, false)
 and coalesce((quote ->> 'premium_hardcover_amount')::integer, 0) > 0,
 (quote ->> 'base_book_amount')::integer,
 (quote ->> 'premium_hardcover_amount')::integer,
 snapshot
 ) returning * into order_row;

 if code_row.id is not null then
 insert into public.discount_redemptions(
 discount_code_id, campaign_id, commerce_order_id, purchaser_user_id, amount_discounted
 ) values (
 code_row.id, code_row.campaign_id, order_row.id, input_purchaser_user_id,
 (quote ->> 'discount_amount')::integer
 );
 end if;

 return jsonb_build_object('order', to_jsonb(order_row), 'quote', quote);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_commerce_refund(input_payment_intent_id text, input_refund_amount integer, input_is_full_refund boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare order_row public.commerce_orders%rowtype;
begin
 select * into order_row from public.commerce_orders
 where stripe_payment_intent_id = input_payment_intent_id for update;
 if order_row.id is null then return jsonb_build_object('found', false); end if;

 update public.commerce_orders set
 refund_amount = greatest(coalesce(refund_amount, 0), coalesce(input_refund_amount, 0)),
 status = case when input_is_full_refund then 'refunded' else status end,
 refunded_at = case when input_is_full_refund then coalesce(refunded_at, now()) else refunded_at end
 where id = order_row.id returning * into order_row;

 if input_is_full_refund then
 update public.discount_redemptions set status = 'refunded'
 where commerce_order_id = order_row.id and status = 'redeemed';
 update public.gift_orders set guarantee_status = 'refunded'
 where commerce_order_id = order_row.id;

 if order_row.order_type = 'self' and order_row.book_project_id is not null then
 perform set_config('app.payment_flow', 'on', true);
 if order_row.includes_base_book then
 update public.book_projects set access_status = 'refunded'
 where id = order_row.book_project_id;
 end if;
 if order_row.includes_premium_hardcover then
 update public.book_projects set premium_hardcover_status = 'refunded'
 where id = order_row.book_project_id
 and premium_hardcover_order_id = order_row.id;
 end if;
 end if;
 end if;
 return jsonb_build_object('found', true, 'order', to_jsonb(order_row));
end;
$function$

CREATE OR REPLACE FUNCTION public.create_story_relationship_invite(input_book_project_id uuid, input_email text, input_invite_type text, input_invitee_name text DEFAULT NULL::text, input_relationship_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 normalized_email text := lower(btrim(coalesce(input_email, '')));
 target_preference public.story_sharing_preferences%rowtype;
 new_id uuid;
begin
 if not exists (
 select 1 from public.book_projects bp
 where bp.id = input_book_project_id and bp.owner_user_id = auth.uid() and bp.status = 'active'
 ) then raise exception 'Project owner access is required'; end if;
 if normalized_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
 raise exception 'A valid email address is required';
 end if;
 if input_invite_type not in ('family', 'selected') then raise exception 'Invalid invitation type'; end if;

 insert into public.story_sharing_preferences (book_project_id, owner_person_id, live_scope)
 select bp.id, bp.subject_person_id, 'private' from public.book_projects bp where bp.id = input_book_project_id
 on conflict on constraint story_sharing_preferences_project_unique do nothing;

 update public.story_sharing_preferences
 set
 family_sharing_enabled = family_sharing_enabled or input_invite_type = 'family',
 selected_sharing_enabled = selected_sharing_enabled or input_invite_type = 'selected',
 live_scope = case
 when selected_sharing_enabled or input_invite_type = 'selected' then 'selected'
 when family_sharing_enabled or input_invite_type = 'family' then 'family'
 else 'private'
 end,
 initial_setup_completed_at = coalesce(initial_setup_completed_at, now()),
 updated_at = now()
 where book_project_id = input_book_project_id;

 update public.story_relationship_invites
 set status = 'revoked', revoked_at = now(), updated_at = now()
 where book_project_id = input_book_project_id
 and lower(btrim(invitee_email)) = normalized_email
 and invite_type = input_invite_type
 and status in ('pending', 'accepted');

 insert into public.story_relationship_invites (
 book_project_id, inviter_user_id, invitee_email, invite_type,
 invitee_name, relationship_label
 ) values (
 input_book_project_id, auth.uid(), normalized_email, input_invite_type,
 nullif(btrim(coalesce(input_invitee_name, '')), ''),
 case when input_invite_type = 'family' then coalesce(input_relationship_label, 'other') else null end
 ) returning id into new_id;
 return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_story_relationship_invite(input_invite_id uuid, input_accept boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 target public.story_relationship_invites%rowtype;
 target_family_id uuid;
 target_pref_id uuid;
 self_person_id uuid;
begin
 select * into target from public.story_relationship_invites i
 where i.id = input_invite_id and i.status = 'pending'
 and lower(btrim(i.invitee_email)) = lower(btrim(coalesce(auth.jwt() ->> 'email', '')))
 for update;
 if target.id is null then raise exception 'Invitation is not available'; end if;
 if not input_accept then
 update public.story_relationship_invites set status = 'declined', updated_at = now() where id = target.id;
 return true;
 end if;
 select upl.person_id into self_person_id from public.user_person_links upl
 where upl.user_id = auth.uid() and upl.role = 'self' order by upl.created_at asc limit 1;
 select bp.family_id into target_family_id from public.book_projects bp where bp.id = target.book_project_id;
 select pref.id into target_pref_id from public.story_sharing_preferences pref where pref.book_project_id = target.book_project_id;

 if target.invite_type = 'family' then
 insert into public.family_memberships (family_id, user_id, person_id, relationship_label, invited_by_user_id, status, accepted_at)
 values (target_family_id, auth.uid(), self_person_id, coalesce(target.relationship_label, 'other'), target.inviter_user_id, 'active', now())
 on conflict (family_id, user_id) do update set person_id = excluded.person_id, relationship_label = excluded.relationship_label,
 status = 'active', accepted_at = now(), revoked_at = null, updated_at = now();
 end if;

 if target_pref_id is not null then
 insert into public.story_share_recipients (sharing_preference_id, recipient_person_id, recipient_user_id, recipient_phase, source, status, meta_json)
 values (target_pref_id, self_person_id, auth.uid(), 'live', target.invite_type, 'active', jsonb_build_object('relationship_invite_id', target.id))
 on conflict do nothing;
 update public.story_share_recipients set status = 'active', updated_at = now()
 where sharing_preference_id = target_pref_id and recipient_user_id = auth.uid()
 and recipient_phase = 'live' and source = target.invite_type;
 end if;
 update public.story_relationship_invites set status = 'accepted', recipient_user_id = auth.uid(), recipient_person_id = self_person_id,
 accepted_at = now(), updated_at = now() where id = target.id;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_story_relationship(input_book_project_id uuid, input_relationship_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare target public.story_relationship_invites%rowtype;
begin
 if not exists (select 1 from public.book_projects bp where bp.id = input_book_project_id and bp.owner_user_id = auth.uid())
 then raise exception 'Project owner access is required'; end if;
 select * into target from public.story_relationship_invites where id = input_relationship_id and book_project_id = input_book_project_id;
 if target.id is null then return false; end if;
 update public.story_relationship_invites set status = 'revoked', revoked_at = now(), updated_at = now() where id = target.id;
 update public.story_share_recipients r set status = 'revoked', updated_at = now()
 from public.story_sharing_preferences pref where pref.id = r.sharing_preference_id and pref.book_project_id = input_book_project_id
 and r.recipient_user_id = target.recipient_user_id and r.source = target.invite_type;
 if target.invite_type = 'family' and target.recipient_user_id is not null then
 update public.family_memberships fm set status = 'revoked', revoked_at = now(), updated_at = now()
 from public.book_projects bp where bp.id = input_book_project_id and fm.family_id = bp.family_id and fm.user_id = target.recipient_user_id;
 end if;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.disable_story_sharing_scope(input_book_project_id uuid, input_scope text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
 if not exists (select 1 from public.book_projects bp where bp.id = input_book_project_id and bp.owner_user_id = auth.uid())
 then raise exception 'Project owner access is required'; end if;
 if input_scope = 'selected' then
 update public.project_supporters set status = 'revoked', revoked_at = now(), updated_at = now()
 where book_project_id = input_book_project_id and status = 'active';
 update public.project_invites set status = 'declined'
 where book_project_id = input_book_project_id and role = 'supporter' and status = 'pending';
 update public.story_share_recipients r set status = 'revoked', updated_at = now()
 from public.story_sharing_preferences pref where pref.id = r.sharing_preference_id
 and pref.book_project_id = input_book_project_id and r.source = 'supporter';
 update public.story_sharing_preferences set selected_sharing_enabled = false,
 live_scope = case when family_sharing_enabled then 'family' else 'private' end, updated_at = now()
 where book_project_id = input_book_project_id;
 elsif input_scope = 'family' then
 update public.story_sharing_preferences set family_sharing_enabled = false,
 live_scope = case when selected_sharing_enabled then 'selected' else 'private' end, updated_at = now()
 where book_project_id = input_book_project_id;
 else raise exception 'Invalid sharing scope'; end if;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_commerce_quote(input_product_code text DEFAULT 'self_book_v1'::text, input_discount_code text DEFAULT NULL::text, input_include_gift_package boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 product_row public.commerce_products%rowtype;
 package_row public.commerce_products%rowtype;
 code_row public.discount_codes%rowtype;
 campaign_row public.discount_campaigns%rowtype;
 normalized text := public.normalize_discount_code(input_discount_code);
 discount_amount integer := 0;
 campaign_used integer := 0;
begin
 select * into product_row from public.commerce_products
 where product_code = input_product_code and is_active = true;
 if product_row.product_code is null then
 raise exception '商品が見つかりません' using errcode = 'P0002';
 end if;

 if input_include_gift_package then
 select * into package_row from public.commerce_products
 where product_code = 'gift_package_v1' and is_active = true;
 end if;

 if normalized <> '' then
 select c.* into code_row from public.discount_codes c
 where c.normalized_code = normalized and c.is_active = true;
 if code_row.id is null then raise exception '割引コードを確認できません' using errcode = '22023'; end if;
 select * into campaign_row from public.discount_campaigns where id = code_row.campaign_id;
 if campaign_row.status not in ('active', 'scheduled')
 or (campaign_row.starts_at is not null and campaign_row.starts_at > now())
 or (campaign_row.ends_at is not null and campaign_row.ends_at <= now())
 or (code_row.expires_at is not null and code_row.expires_at <= now()) then
 raise exception 'この割引コードは現在利用できません' using errcode = '22023';
 end if;
 if campaign_row.product_code <> product_row.product_code then
 raise exception 'この商品には利用できない割引コードです' using errcode = '22023';
 end if;
 if code_row.max_redemptions is not null and code_row.redemption_count >= code_row.max_redemptions then
 raise exception 'この割引コードは使用済みです' using errcode = '22023';
 end if;
 if campaign_row.max_redemptions is not null then
 select count(*) into campaign_used from public.discount_redemptions
 where campaign_id = campaign_row.id and status in ('pending', 'redeemed');
 if campaign_used >= campaign_row.max_redemptions then
 raise exception 'このキャンペーンは終了しました' using errcode = '22023';
 end if;
 end if;
 if campaign_row.one_per_account and auth.uid() is not null and exists (
 select 1 from public.discount_redemptions
 where campaign_id = campaign_row.id and purchaser_user_id = auth.uid() and status = 'redeemed'
 ) then
 raise exception 'この割引は1アカウントにつき1回利用できます' using errcode = '22023';
 end if;
 discount_amount := case campaign_row.discount_type
 when 'full' then product_row.amount_jpy
 when 'percent' then round(product_row.amount_jpy * campaign_row.discount_value / 100.0)::integer
 else least(product_row.amount_jpy, campaign_row.discount_value::integer)
 end;
 end if;

 return jsonb_build_object(
 'product_code', product_row.product_code,
 'product_name', product_row.display_name,
 'amount_subtotal', product_row.amount_jpy,
 'gift_package_amount', case when input_include_gift_package then coalesce(package_row.amount_jpy, 0) else 0 end,
 'discount_amount', discount_amount,
 'amount_total', product_row.amount_jpy - discount_amount + case when input_include_gift_package then coalesce(package_row.amount_jpy, 0) else 0 end,
 'currency', product_row.currency,
 'tax_included', product_row.tax_included,
 'domestic_shipping_included', product_row.domestic_shipping_included,
 'discount_code_id', code_row.id,
 'discount_code', code_row.code,
 'campaign_id', campaign_row.id,
 'campaign_name', campaign_row.name,
 'campaign_type', campaign_row.campaign_type
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_commerce_order(input_purchaser_user_id uuid, input_book_project_id uuid, input_order_type text, input_product_code text, input_discount_code text, input_include_gift_package boolean, input_gift jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 quote jsonb;
 code_row public.discount_codes%rowtype;
 campaign_row public.discount_campaigns%rowtype;
 order_row public.commerce_orders%rowtype;
 guarantee_days integer := 40;
 reservation_minutes integer := 60;
 claim_token text;
 claim_code text;
 used_count integer;
begin
 if input_order_type not in ('self', 'gift') then raise exception '注文種別が不正です'; end if;
 if input_purchaser_user_id is null then raise exception '購入者が必要です'; end if;

 select coalesce(integer_value, 40) into guarantee_days from public.commerce_settings where setting_key = 'gift_guarantee_days';
 select coalesce(integer_value, 60) into reservation_minutes from public.commerce_settings where setting_key = 'checkout_reservation_minutes';

 update public.commerce_orders set status = 'expired'
 where status = 'checkout_pending' and created_at < now() - make_interval(mins => reservation_minutes);
 update public.discount_redemptions r set status = 'released'
 where status = 'pending' and exists (
 select 1 from public.commerce_orders o where o.id = r.commerce_order_id and o.status = 'expired'
 );

 quote := public.get_commerce_quote(input_product_code, input_discount_code, input_include_gift_package);
 if quote ->> 'discount_code_id' is not null then
 select * into code_row from public.discount_codes where id = (quote ->> 'discount_code_id')::uuid for update;
 select * into campaign_row from public.discount_campaigns where id = code_row.campaign_id for update;
 select count(*) into used_count from public.discount_redemptions
 where discount_code_id = code_row.id and status in ('pending', 'redeemed');
 if code_row.max_redemptions is not null and used_count >= code_row.max_redemptions then
 raise exception 'この割引コードは使用中または使用済みです' using errcode = '22023';
 end if;
 if campaign_row.one_per_account and exists (
 select 1 from public.discount_redemptions
 where campaign_id = campaign_row.id and purchaser_user_id = input_purchaser_user_id and status in ('pending', 'redeemed')
 ) then
 raise exception 'この割引は1アカウントにつき1回利用できます' using errcode = '22023';
 end if;
 end if;

 insert into public.commerce_orders(
 purchaser_user_id, book_project_id, order_type, product_code,
 amount_subtotal, gift_package_amount, discount_amount, amount_total,
 currency, discount_code_id, status
 ) values (
 input_purchaser_user_id,
 case when input_order_type = 'self' then input_book_project_id else null end,
 input_order_type,
 input_product_code,
 (quote ->> 'amount_subtotal')::integer,
 (quote ->> 'gift_package_amount')::integer,
 (quote ->> 'discount_amount')::integer,
 (quote ->> 'amount_total')::integer,
 quote ->> 'currency',
 nullif(quote ->> 'discount_code_id', '')::uuid,
 'checkout_pending'
 ) returning * into order_row;

 if code_row.id is not null then
 insert into public.discount_redemptions(
 discount_code_id, campaign_id, commerce_order_id, purchaser_user_id, amount_discounted
 ) values (
 code_row.id, code_row.campaign_id, order_row.id, input_purchaser_user_id,
 (quote ->> 'discount_amount')::integer
 );
 end if;

 if input_order_type = 'gift' then
 claim_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
 claim_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
 insert into public.gift_orders(
 commerce_order_id, recipient_name, recipient_email, gift_message,
 package_selected, package_status, shipping_address, guarantee_days,
 claim_token, claim_code
 ) values (
 order_row.id,
 nullif(btrim(input_gift ->> 'recipient_name'), ''),
 nullif(lower(btrim(input_gift ->> 'recipient_email')), ''),
 nullif(btrim(input_gift ->> 'gift_message'), ''),
 input_include_gift_package,
 case when input_include_gift_package then 'pending' else 'not_requested' end,
 coalesce(input_gift -> 'shipping_address', '{}'::jsonb),
 guarantee_days,
 claim_token,
 claim_code
 );
 end if;

 return jsonb_build_object('order', to_jsonb(order_row), 'quote', quote);
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_admin_attention_item(input_attention_id uuid, input_reason text, input_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 normalized_reason text := lower(btrim(coalesce(input_reason, '')));
 resolved public.admin_attention_items;
begin
 if auth.uid() is null or not public.is_tateyoko_admin() then
 raise exception 'Admin access required' using errcode = '42501';
 end if;

 if normalized_reason not in ('system_fixed', 'contacted_elsewhere', 'no_action_needed') then
 raise exception 'Invalid resolution reason' using errcode = '22023';
 end if;

 update public.admin_attention_items
 set
 status = 'resolved',
 resolved_at = now(),
 resolved_by = auth.uid(),
 resolution_reason = normalized_reason,
 resolution_note = nullif(btrim(coalesce(input_note, '')), ''),
 updated_at = now()
 where id = input_attention_id
 and status = 'open'
 returning * into resolved;

 if resolved.id is null then
 raise exception 'Open attention item not found' using errcode = 'P0002';
 end if;

 insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, metadata)
 values (
 auth.uid(), 'resolve_attention', 'admin_attention_item', resolved.id,
 jsonb_strip_nulls(jsonb_build_object(
 'book_project_id', resolved.book_project_id,
 'reason', normalized_reason,
 'note', nullif(btrim(coalesce(input_note, '')), '')
 ))
 );

 return to_jsonb(resolved);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_dashboard(input_search text DEFAULT NULL::text, input_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 base_result jsonb;
 merged_projects jsonb := '[]'::jsonb;
 merged_attention jsonb := '[]'::jsonb;
 old_attention_ids uuid[] := '{}'::uuid[];
 additional_attention_count integer := 0;
begin
 if auth.uid() is null or not public.is_tateyoko_admin() then
 raise exception 'Admin access required' using errcode = '42501';
 end if;

 base_result := public.get_admin_dashboard_without_delivery_attention(input_search, input_limit);

 select coalesce(array_agg((item ->> 'id')::uuid), '{}'::uuid[])
 into old_attention_ids
 from jsonb_array_elements(coalesce(base_result -> 'attention', '[]'::jsonb)) item;

 with issue_stats as (
 select
 ai.book_project_id,
 count(*)::integer as attention_item_count,
 count(*) filter (where ai.attention_type = 'question_delivery_failed')::integer as delivery_failure_count,
 case when bool_or(ai.title = '配信失敗') then '配信失敗' else '一部失敗' end as attention_reason,
 case when bool_or(ai.severity = 'error') then 'error' else 'warning' end as health_status
 from public.admin_attention_items ai
 where ai.status = 'open'
 group by ai.book_project_id
 ), rows as (
 select
 project.value || jsonb_strip_nulls(jsonb_build_object(
 'attention_item_count', stats.attention_item_count,
 'delivery_failure_count', stats.delivery_failure_count,
 'attention_reason', coalesce(nullif(project.value ->> 'attention_reason', ''), stats.attention_reason),
 'health_status', case
 when coalesce(project.value ->> 'health_status', 'ok') <> 'ok' then project.value ->> 'health_status'
 else stats.health_status
 end
 )) as value
 from jsonb_array_elements(coalesce(base_result -> 'projects', '[]'::jsonb)) project
 left join issue_stats stats on stats.book_project_id = (project.value ->> 'id')::uuid
 )
 select coalesce(jsonb_agg(value order by value ->> 'last_activity_at' desc), '[]'::jsonb)
 into merged_projects
 from rows;

 select coalesce(jsonb_agg(project order by
 case project ->> 'health_status' when 'error' then 1 when 'warning' then 2 else 3 end,
 project ->> 'last_activity_at' desc
 ), '[]'::jsonb)
 into merged_attention
 from jsonb_array_elements(merged_projects) project
 where nullif(project ->> 'attention_reason', '') is not null;

 select count(distinct ai.book_project_id)::integer
 into additional_attention_count
 from public.admin_attention_items ai
 where ai.status = 'open'
 and not (ai.book_project_id = any(old_attention_ids));

 base_result := jsonb_set(base_result, '{projects}', merged_projects, true);
 base_result := jsonb_set(base_result, '{attention}', merged_attention, true);
 base_result := jsonb_set(
 base_result,
 '{metrics,attention_count}',
 to_jsonb(coalesce((base_result #>> '{metrics,attention_count}')::integer, 0) + additional_attention_count),
 true
 );

 return base_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_own_profile_name(input_family_name text, input_given_name text)
 RETURNS TABLE(family_name text, given_name text, display_name text, preferred_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 f text := btrim(coalesce(input_family_name, ''));
 g text := btrim(coalesce(input_given_name, ''));
 d text;
 previous public.profiles;
begin
 if auth.uid() is null then
 raise exception 'Authentication is required' using errcode = '42501';
 end if;
 if f = '' or g = '' then
 raise exception 'Family name and given name are required' using errcode = '22023';
 end if;

 d := f || ' ' || g;
 select * into previous from public.profiles where id = auth.uid() for update;
 if previous.id is null then
 raise exception 'Profile not found' using errcode = 'P0002';
 end if;

 if previous.family_name is not distinct from f
 and previous.given_name is not distinct from g
 and previous.display_name is not distinct from d then
 return query select f, g, d, g || 'さん';
 return;
 end if;

 insert into public.profile_name_change_logs (
 user_id, previous_family_name, previous_given_name, previous_display_name,
 new_family_name, new_given_name, new_display_name
 ) values (
 auth.uid(), previous.family_name, previous.given_name, previous.display_name,
 f, g, d
 );

 update public.profiles
 set family_name = f, given_name = g, display_name = d, preferred_name = g || 'さん'
 where id = auth.uid();

 insert into public.activity_logs (
 actor_user_id, subject_user_id, action, entity_type, entity_id,
 source, outcome, metadata
 ) values (
 auth.uid(), auth.uid(), 'account_name_changed', 'account', auth.uid(),
 'app', 'success', jsonb_build_object(
 'previous_display_name', previous.display_name,
 'new_display_name', d
 )
 );

 return query select f, g, d, g || 'さん';
end;
$function$

CREATE OR REPLACE FUNCTION public.set_voice_publication_access_code(input_publication_id uuid, input_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
 normalized_code text := btrim(coalesce(input_code, ''));
begin
 if auth.role() <> 'service_role' then
 raise exception 'forbidden';
 end if;

 if normalized_code = '' then
 update public.voice_publications
 set access_mode = 'link',
 access_code_hash = null,
 access_code_changed_at = now()
 where id = input_publication_id;
 else
 if normalized_code !~ '^[0-9]{4,8}$' then
 raise exception 'access code must be 4 to 8 digits';
 end if;

 update public.voice_publications
 set access_mode = 'code',
 access_code_hash = crypt(normalized_code, gen_salt('bf', 10)),
 access_code_changed_at = now()
 where id = input_publication_id;
 end if;

 delete from public.voice_publication_access_sessions
 where publication_id = input_publication_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_video_story_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
 existing_count integer;
begin
 -- Serialize inserts for one project so concurrent uploads cannot create a
 -- third item between the count and insert.
 perform 1
 from public.book_projects
 where id = new.book_project_id
 for update;

 select count(*) into existing_count
 from public.video_stories story
 where story.book_project_id = new.book_project_id;

 if existing_count >= 2 then
 raise exception 'A book can contain at most two videos';
 end if;

 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_voice_publication_request(input_publication_id uuid, input_client_hash text, input_request_kind text)
 RETURNS TABLE(allowed boolean, circuit_open boolean, retry_after_seconds integer, client_count bigint, publication_window_count bigint, publication_day_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 normalized_client_hash text := left(btrim(coalesce(input_client_hash, '')), 128);
 normalized_kind text := lower(btrim(coalesce(input_request_kind, '')));
 current_status text;
 now_at timestamptz := clock_timestamp();
 ten_minute_window timestamptz;
 day_window timestamptz;
 client_limit bigint;
 client_total bigint;
 publication_total bigint;
 day_total bigint;
 open_reason text := '';
begin
 if auth.role() <> 'service_role' then
 raise exception 'forbidden';
 end if;
 if normalized_client_hash = '' or normalized_kind not in ('metadata', 'asset', 'video_asset') then
 raise exception 'invalid rate-limit input';
 end if;

 select publication.status
 into current_status
 from public.voice_publications publication
 where publication.id = input_publication_id;

 if current_status is distinct from 'published' then
 return query select false, true, 600, 0::bigint, 0::bigint, 0::bigint;
 return;
 end if;

 ten_minute_window := date_bin(interval '10 minutes', now_at, timestamptz '2001-01-01 00:00:00+00');
 day_window := date_trunc('day', now_at);
 client_limit := case
 when normalized_kind = 'metadata' then 30
 when normalized_kind = 'video_asset' then 40
 else 120
 end;

 insert into public.voice_publication_request_windows as counter (
 publication_id, counter_key, request_kind, window_started_at, request_count
 ) values (
 input_publication_id, normalized_client_hash, normalized_kind, ten_minute_window, 1
 )
 on conflict (publication_id, counter_key, request_kind, window_started_at)
 do update set request_count = counter.request_count + 1,
 updated_at = now_at
 returning counter.request_count into client_total;

 insert into public.voice_publication_request_windows as counter (
 publication_id, counter_key, request_kind, window_started_at, request_count
 ) values (
 input_publication_id, '*', 'all', ten_minute_window, 1
 )
 on conflict (publication_id, counter_key, request_kind, window_started_at)
 do update set request_count = counter.request_count + 1,
 updated_at = now_at
 returning counter.request_count into publication_total;

 insert into public.voice_publication_request_windows as counter (
 publication_id, counter_key, request_kind, window_started_at, request_count
 ) values (
 input_publication_id, '*', 'all_day', day_window, 1
 )
 on conflict (publication_id, counter_key, request_kind, window_started_at)
 do update set request_count = counter.request_count + 1,
 updated_at = now_at
 returning counter.request_count into day_total;

 if publication_total = 1 then
 delete from public.voice_publication_request_windows
 where publication_id = input_publication_id
 and window_started_at < now_at - interval '2 days';
 end if;

 if publication_total > 500 then
 open_reason := 'automatic_playback_limit:burst';
 elsif day_total > 5000 then
 open_reason := 'automatic_playback_limit:daily';
 end if;

 if open_reason <> '' then
 update public.voice_publications
 set status = 'disabled',
 disabled_at = now_at,
 disabled_reason = open_reason
 where id = input_publication_id
 and status = 'published';

 return query select false, true, 600, client_total, publication_total, day_total;
 return;
 end if;

 if client_total > client_limit then
 return query select
 false,
 false,
 greatest(1, extract(epoch from (ten_minute_window + interval '10 minutes' - now_at))::integer),
 client_total,
 publication_total,
 day_total;
 return;
 end if;

 return query select true, false, 0, client_total, publication_total, day_total;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_family_invitation_after_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 invitation_row public.family_story_invitations%rowtype;
 linked_gift public.gift_orders%rowtype;
begin
 if new.status in ('paid', 'zero_paid')
 and old.status is distinct from new.status then
 update public.family_story_invitations i
 set status = case when new.order_type = 'self' then 'started' else 'ready' end,
 started_at = case when new.order_type = 'self' then coalesce(i.started_at, now()) else i.started_at end,
 package_status = case
 when i.delivery_method = 'package' then 'pending'
 else i.package_status
 end,
 email_delivery_status = case
 when i.delivery_method = 'email' then 'pending'
 else i.email_delivery_status
 end,
 gift_order_id = coalesce(
 i.gift_order_id,
 (select g.id from public.gift_orders g where g.commerce_order_id = new.id)
 )
 where i.commerce_order_id = new.id
 and i.status in ('awaiting_payment', 'continuation_awaiting_payment', 'trial_completed', 'continuation_declined')
 returning * into invitation_row;

 if invitation_row.id is not null
 and invitation_row.recipient_project_id is not null then
 select * into linked_gift
 from public.gift_orders g
 where g.commerce_order_id = new.id;

 if linked_gift.id is not null then
 perform set_config('app.payment_flow', 'on', true);
 update public.book_projects
 set access_status = 'gifted',
 purchaser_user_id = new.purchaser_user_id,
 purchased_at = new.purchased_at,
 commerce_order_id = new.id
 where id = invitation_row.recipient_project_id;

 update public.commerce_orders
 set book_project_id = invitation_row.recipient_project_id
 where id = new.id;

 update public.gift_orders
 set claimed_by_user_id = invitation_row.recipient_user_id,
 claimed_at = coalesce(claimed_at, now()),
 recipient_project_id = invitation_row.recipient_project_id
 where id = linked_gift.id;

 update public.family_story_invitations
 set status = 'started', started_at = coalesce(started_at, now())
 where id = invitation_row.id;
 end if;
 end if;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_family_invitation_continuation(input_invitation_id uuid, input_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 invitation public.family_story_invitations%rowtype;
begin
 if auth.uid() is null then
 raise exception 'ログインが必要です' using errcode = '42501';
 end if;
 if input_decision not in ('gift', 'decline') then
 raise exception '選択を確認してください' using errcode = '22023';
 end if;

 update public.family_story_invitations
 set continuation_decision = input_decision,
 continuation_decided_at = now(),
 status = case when input_decision = 'gift' then 'continuation_awaiting_payment' else 'continuation_declined' end
 where id = input_invitation_id
 and inviter_user_id = auth.uid()
 and status = 'trial_completed'
 returning * into invitation;

 if invitation.id is null then
 raise exception 'このお試しの続きを変更できません' using errcode = '22023';
 end if;
 return to_jsonb(invitation);
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_experience_refund_subject(input_request_id uuid, input_subject_person_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare r public.experience_refund_requests%rowtype;
begin
  if input_subject_person_id is null then raise exception 'A verified subject is required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(input_subject_person_id::text, 0));
  select * into r from public.experience_refund_requests where id = input_request_id for update;
  if r.id is null or r.status <> 'requested' then raise exception 'Request cannot be assigned'; end if;
  if r.subject_person_id is not null and r.subject_person_id <> input_subject_person_id then
    raise exception 'Cannot change the subject of a refund';
  end if;
  update public.experience_refund_requests set subject_person_id = input_subject_person_id, identity_review_required = false
  where id = r.id returning * into r;
  return to_jsonb(r);
end;
$function$

CREATE OR REPLACE FUNCTION public.register_experience_contract(input_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  o public.commerce_orders%rowtype;
  p public.book_projects%rowtype;
  c public.experience_contracts%rowtype;
  base_amount integer;
begin
  select * into o from public.commerce_orders where id = input_order_id for update;
  select * into c from public.experience_contracts where order_id = input_order_id;
  if c.order_id is not null then return to_jsonb(c); end if;
  if o.id is null or o.status <> 'checkout_pending' or o.order_type not in ('self', 'gift')
    or not o.includes_base_book then
    raise exception 'Only a new unpaid base-book order can adopt v2 terms';
  end if;
  -- Finish-time options use separate orders; don't guess mixed-order allocations.
  if coalesce(o.standard_extra_copy_count, 0) > 0 or coalesce(o.premium_copy_count, 0) > 0 then
    raise exception 'V2 base purchase must not include reprint options';
  end if;
  if o.book_project_id is not null then
    select * into p from public.book_projects where id = o.book_project_id;
    if p.subject_person_id is null then raise exception 'A subject Person is required'; end if;
  elsif o.order_type = 'self' then
    raise exception 'A self purchase requires a project';
  end if;
  base_amount := greatest(0, coalesce(nullif(o.base_book_amount, 0), o.amount_subtotal, 0) - o.discount_amount);
  insert into public.experience_contracts (
    order_id, book_project_id, subject_person_id, purchaser_user_id, purchase_kind, guarantee_days, base_paid_amount
  ) values (o.id, p.id, p.subject_person_id, o.purchaser_user_id, o.order_type,
    case when o.order_type = 'gift' then 45 else 30 end, base_amount)
  returning * into c;
  return to_jsonb(c);
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_experience_payment(input_order_id uuid, input_confirmed_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare o public.commerce_orders%rowtype; c public.experience_contracts%rowtype;
begin
  select * into o from public.commerce_orders where id = input_order_id for update;
  select * into c from public.experience_contracts where order_id = input_order_id for update;
  if c.order_id is null then return jsonb_build_object('version', 'legacy'); end if;
  if o.status not in ('paid', 'zero_paid') then raise exception 'Payment is not confirmed'; end if;
  if input_confirmed_at is null or input_confirmed_at < o.created_at - interval '5 minutes'
    or input_confirmed_at > now() + interval '5 minutes' then
    raise exception 'Invalid payment confirmation time';
  end if;
  if c.payment_confirmed_at is null then
    update public.experience_contracts set payment_confirmed_at = input_confirmed_at,
      guarantee_expires_at = input_confirmed_at + make_interval(days => guarantee_days),
      gift_activation_expires_at = case when purchase_kind = 'gift' then input_confirmed_at + interval '6 months' end,
      production_started_at = case when purchase_kind = 'self' then input_confirmed_at end,
      production_expires_at = case when purchase_kind = 'self' then input_confirmed_at + interval '1 year' end
    where order_id = input_order_id returning * into c;
  end if;
  return to_jsonb(c);
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_gift_experience_contract(input_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; g public.gift_orders%rowtype; p public.book_projects%rowtype;
begin
  select * into c from public.experience_contracts where order_id = input_order_id for update;
  if c.order_id is null then return jsonb_build_object('version', 'legacy'); end if;
  select * into g from public.gift_orders where commerce_order_id = input_order_id;
  select * into p from public.book_projects where id = g.recipient_project_id;
  if c.purchase_kind <> 'gift' or c.payment_confirmed_at is null or c.refund_confirmed_at is not null
    or g.claimed_at is null or p.subject_person_id is null then raise exception 'Claimed paid gift is required'; end if;
  if exists (select 1 from public.experience_refund_requests where order_id = input_order_id) then
    raise exception 'A refund request is being processed';
  end if;
  if c.book_project_id is not null and (c.book_project_id <> p.id or c.subject_person_id <> p.subject_person_id) then
    raise exception 'A gift cannot be reassigned to another Person';
  end if;
  update public.experience_contracts set book_project_id = p.id, subject_person_id = p.subject_person_id
  where order_id = input_order_id returning * into c;
  return to_jsonb(c);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_experience_access(input_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype;
begin
  if not public.can_confirm_experience_intent(input_project_id) then
    raise exception 'Project access is required' using errcode = '42501';
  end if;
  select * into c from public.experience_contracts where book_project_id = input_project_id
    order by (refund_confirmed_at is null) desc, created_at desc limit 1;
  if c.order_id is null then return jsonb_build_object('policy_version', 'legacy'); end if;
  return jsonb_build_object('policy_version', c.policy_version,
    'paid', c.payment_confirmed_at is not null, 'main_started_at', c.main_experience_started_at,
    'guarantee_days', c.guarantee_days, 'guarantee_expires_at', c.guarantee_expires_at,
    'production_started_at', c.production_started_at, 'production_expires_at', c.production_expires_at,
    'gift_activation_expires_at', c.gift_activation_expires_at,
    'refund_confirmed_at', c.refund_confirmed_at, 'export_available_until', c.export_available_until,
    'can_create', c.payment_confirmed_at is not null and c.refund_confirmed_at is null
      and c.production_started_at is not null and now() <= c.production_expires_at
      and not exists (select 1 from public.experience_refund_requests r where r.order_id = c.order_id),
    'retention_review_required', c.export_available_until is not null and now() > c.export_available_until);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_experience_refund_result(input_request_id uuid, input_stripe_refund_id text, input_status text, input_amount integer, input_confirmed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; r public.experience_refund_requests%rowtype; target_order uuid;
begin
  select order_id into target_order from public.experience_refund_requests where id = input_request_id;
  -- Same lock order as request/start: contract first, then request.
  select * into c from public.experience_contracts where order_id = target_order for update;
  select * into r from public.experience_refund_requests where id = input_request_id for update;
  if r.id is null then raise exception 'Refund request not found'; end if;
  if r.identity_review_required or r.subject_person_id is null then raise exception 'Verify the subject before refund execution'; end if;
  if input_status is null or input_status not in ('pending', 'failed', 'succeeded') or nullif(input_stripe_refund_id, '') is null
    or input_amount is distinct from r.requested_amount then raise exception 'Refund result does not match request'; end if;
  if r.stripe_refund_id is not null and r.stripe_refund_id <> input_stripe_refund_id then
    raise exception 'Different processor refund requires review';
  end if;
  if r.status = 'succeeded' then return to_jsonb(r); end if;
  if input_status = 'succeeded' and (input_confirmed_at is null or input_confirmed_at < r.requested_at - interval '5 minutes'
    or input_confirmed_at > now() + interval '5 minutes') then raise exception 'Invalid refund confirmation time'; end if;
  update public.experience_refund_requests set stripe_refund_id = input_stripe_refund_id,
    status = input_status, confirmed_at = case when input_status = 'succeeded' then input_confirmed_at else null end
  where id = r.id returning * into r;
  if input_status = 'succeeded' then
    update public.experience_contracts set refund_confirmed_at = input_confirmed_at,
      export_available_until = input_confirmed_at + interval '30 days'
    where order_id = c.order_id;
  end if;
  -- No DELETE here. Expiry leads to review of references, notice and obligations.
  return to_jsonb(r);
end;
$function$

CREATE OR REPLACE FUNCTION public.start_main_experience(input_project_id uuid, input_subject_intent_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; p public.book_projects%rowtype;
begin
  if not public.can_confirm_experience_intent(input_project_id) then
    raise exception 'Project access is required' using errcode = '42501';
  end if;
  if input_subject_intent_confirmed is distinct from true then raise exception 'The subject must choose to begin'; end if;
  select * into c from public.experience_contracts
    where book_project_id = input_project_id and payment_confirmed_at is not null and refund_confirmed_at is null
    for update;
  if c.order_id is null then raise exception 'An active v2 purchase is required'; end if;
  if c.production_started_at is null or now() > c.production_expires_at then raise exception 'Production period is not active'; end if;
  if exists (select 1 from public.experience_refund_requests where order_id = c.order_id) then
    raise exception 'A refund request is being processed';
  end if;
  if c.main_experience_started_at is not null then
    return jsonb_build_object('main_experience_started_at', c.main_experience_started_at);
  end if;
  select * into p from public.book_projects where id = input_project_id;
  if p.subject_person_id is distinct from c.subject_person_id then raise exception 'Subject mismatch'; end if;
  if coalesce(p.onboarding_ritual_step, '') not in ('chapter_complete', 'theme_intro', 'completed') then
    raise exception 'Finish the starting chapter before beginning the main experience';
  end if;
  update public.experience_contracts set main_experience_started_at = now(), main_started_by = auth.uid()
  where order_id = c.order_id returning * into c;
  return jsonb_build_object('main_experience_started_at', c.main_experience_started_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.start_paid_starting_chapter(input_project_id uuid, input_subject_intent_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype;
begin
  if not public.can_confirm_experience_intent(input_project_id) then
    raise exception 'Project access is required' using errcode = '42501';
  end if;
  if input_subject_intent_confirmed is distinct from true then raise exception 'The subject must choose to begin'; end if;
  select * into c from public.experience_contracts
    where book_project_id = input_project_id and payment_confirmed_at is not null and refund_confirmed_at is null for update;
  if c.order_id is null then raise exception 'An active v2 purchase is required'; end if;
  if exists (select 1 from public.experience_refund_requests where order_id = c.order_id) then
    raise exception 'A refund request is being processed';
  end if;
  if c.production_started_at is null then
    if c.gift_activation_expires_at is null or now() > c.gift_activation_expires_at then
      raise exception 'Please contact support to extend the gift activation period';
    end if;
    update public.experience_contracts set production_started_at = now(), production_expires_at = now() + interval '1 year'
    where order_id = c.order_id returning * into c;
  end if;
  -- Starting the paid introduction must NOT end the refund guarantee.
  if now() > c.production_expires_at then
    raise exception 'Please contact support to extend the production period';
  end if;
  return jsonb_build_object('production_started_at', c.production_started_at,
    'production_expires_at', c.production_expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_experience_refund(input_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; r public.experience_refund_requests%rowtype;
  g public.gift_orders%rowtype; o public.commerce_orders%rowtype; package_refund integer := 0;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select * into c from public.experience_contracts where order_id = input_order_id for update;
  if c.order_id is null or c.purchaser_user_id <> auth.uid() then
    raise exception 'Only the purchaser may request a refund' using errcode = '42501';
  end if;
  select * into r from public.experience_refund_requests where order_id = input_order_id;
  if r.id is not null then return to_jsonb(r); end if;
  -- Accept an unclaimed gift request now, preserving its deadline. Identity
  -- review is required before execution, not before accepting the request.
  if c.subject_person_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(c.subject_person_id::text, 0));
  end if;
  if c.payment_confirmed_at is null or c.refund_confirmed_at is not null or c.base_paid_amount = 0
    or c.main_experience_started_at is not null or now() > c.guarantee_expires_at then
    raise exception 'This order is not eligible for the voluntary guarantee';
  end if;
  if exists (select 1 from public.experience_refund_requests where subject_person_id = c.subject_person_id) then
    raise exception 'This subject already has a guarantee request';
  end if;
  select * into o from public.commerce_orders where id = input_order_id;
  select * into g from public.gift_orders where commerce_order_id = input_order_id;
  if o.gift_package_amount > 0 then
    -- A self-order option has no verified fulfilment state here: manual review.
    if g.id is null then raise exception 'Physical option fulfilment needs review'; end if;
    if g.package_status not in ('shipped', 'delivered') then
      package_refund := least(o.gift_package_amount, greatest(0, o.amount_total - c.base_paid_amount));
    end if;
  end if;
  insert into public.experience_refund_requests(order_id, subject_person_id, requested_by, base_amount, requested_amount, identity_review_required)
  values (c.order_id, c.subject_person_id, auth.uid(), c.base_paid_amount, c.base_paid_amount + package_refund, c.subject_person_id is null)
  returning * into r;
  return to_jsonb(r);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_trial_continuation_intent(input_project_id uuid, input_decision text, input_subject_intent_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare i public.family_story_invitations%rowtype; p public.book_projects%rowtype;
  r public.family_trial_intents%rowtype; trial_total integer; trial_saved integer;
begin
  if not public.can_confirm_experience_intent(input_project_id) then
    raise exception 'Project access is required' using errcode = '42501';
  end if;
  if input_decision is null or input_decision not in ('continue', 'later')
    or input_subject_intent_confirmed is distinct from true then raise exception 'Confirm the subject intention'; end if;
  select * into i from public.family_story_invitations where recipient_project_id = input_project_id for update;
  if i.id is null or i.offer_type <> 'trial_gift'
    or i.status not in ('trial_started', 'trial_completed') then raise exception 'Trial invitation is not awaiting a decision'; end if;
  select * into p from public.book_projects where id = input_project_id;
  if p.subject_person_id is null then raise exception 'Subject Person is required'; end if;
  select count(*), count(*) filter (where uq.status = 'answered' and exists (
    select 1 from public.answers a join public.media_assets m on m.answer_id = a.id
    where a.user_question_id = uq.id and a.book_project_id = p.id
      and a.subject_person_id = p.subject_person_id and m.asset_type = 'audio'
      and nullif(m.storage_path, '') is not null
  )) into trial_total, trial_saved
  from public.user_questions uq where uq.book_project_id = p.id and uq.is_active = true
    and uq.meta_json->>'onboarding_group' = 'trial_experience';
  if trial_total <> 3 or trial_saved <> 3 then raise exception 'Three saved trial recordings are required'; end if;
  select * into r from public.family_trial_intents where invitation_id = i.id;
  if r.decision = input_decision then return to_jsonb(r); end if;
  -- "For now" may become "continue" on a later visit. Cancel unsent old notices.
  update public.experience_notification_outbox set status = 'cancelled'
  where invitation_id = i.id and status in ('pending', 'failed');
  insert into public.family_trial_intents(invitation_id, book_project_id, subject_person_id,
    actor_user_id, decision, subject_intent_confirmed)
  values (i.id, p.id, p.subject_person_id, auth.uid(), input_decision, true)
  on conflict (invitation_id) do update set intent_id = gen_random_uuid(),
    actor_user_id = excluded.actor_user_id, decision = excluded.decision, decided_at = now()
  returning * into r;
  if input_decision = 'continue' then
    insert into public.experience_notification_outbox(dedupe_key, kind, invitation_id, intent_id, recipient_user_id)
    values ('family-continue:' || r.intent_id::text, 'family_continue_requested', i.id, r.intent_id, i.inviter_user_id);
  end if;
  -- A separate outbox owns delivery; this write never sends mail or reveals text.
  return to_jsonb(r);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_experience_refund_event(input_request_id uuid, input_stripe_refund_id text, input_status text, input_amount integer, input_observed_at timestamp with time zone, input_payment_intent_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare r public.experience_refund_requests%rowtype; c public.experience_contracts%rowtype; o public.commerce_orders%rowtype; oid uuid;
begin
 select order_id into oid from experience_refund_requests where id=input_request_id;
 select * into o from commerce_orders where id=oid for update;
 select * into c from experience_contracts where order_id=oid for update;
 select * into r from experience_refund_requests where id=input_request_id for update;
 perform public.require_commerce_mode(o.stripe_mode);
 if o.stripe_payment_intent_id is distinct from input_payment_intent_id then
   raise exception 'Refund payment mismatch';
 end if;
 if input_observed_at is null or input_observed_at>now()+interval '5 minutes'
   or input_observed_at<r.requested_at-interval '5 minutes' then raise exception 'Invalid processor observation time'; end if;
 if input_status not in ('pending','failed','succeeded') or input_status is null
   or r.identity_review_required or r.subject_person_id is null or r.requested_amount is distinct from input_amount
   or nullif(input_stripe_refund_id,'') is null
   or (r.stripe_refund_id is not null and r.stripe_refund_id<>input_stripe_refund_id) then raise exception 'Refund mismatch'; end if;
 if r.processor_observed_at is not null and input_observed_at<r.processor_observed_at then return to_jsonb(r); end if;
 -- A later bank failure is real, not an old pending event. Keep access suspended and require review.
 if r.status='succeeded' and input_status='pending' then return to_jsonb(r); end if;
 update experience_refund_requests set status=input_status,stripe_refund_id=input_stripe_refund_id,
   processor_observed_at=input_observed_at,
   confirmed_at=case when input_status='succeeded' then coalesce(confirmed_at,input_observed_at) else confirmed_at end,
   deletion_review_status=case when input_status='failed' then 'retained' else deletion_review_status end
 where id=r.id returning * into r;
 if input_status='succeeded' then
   update experience_contracts set refund_confirmed_at=coalesce(refund_confirmed_at,r.confirmed_at),
     export_available_until=coalesce(export_available_until,r.confirmed_at+interval '30 days') where order_id=oid;
   perform set_config('app.payment_flow','on',true);
   update book_projects set access_status='refunded' where id=c.book_project_id
     and not exists(select 1 from experience_contracts other where other.book_project_id=c.book_project_id
       and other.order_id<>c.order_id and other.payment_confirmed_at is not null and other.refund_confirmed_at is null);
   -- Full order vs principal-only refund are deliberately different from the production entitlement.
   update commerce_orders set refund_amount=greatest(coalesce(refund_amount,0),input_amount),
     status=case when input_amount>=amount_total then 'refunded' else status end where id=oid;
   update gift_orders set guarantee_status='refunded' where commerce_order_id=oid;
 end if;
 return to_jsonb(r);
end; $function$

CREATE OR REPLACE FUNCTION public.experience_data_allowed(input_project_id uuid, input_write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; r public.experience_refund_requests%rowtype;
begin
 select * into c from experience_contracts where book_project_id=input_project_id and payment_confirmed_at is not null
   order by (refund_confirmed_at is null) desc,created_at desc limit 1;
 if c.order_id is null then return true; end if;
 select * into r from experience_refund_requests where order_id=c.order_id;
 if input_write then
   return ((c.production_started_at is null and c.purchase_kind='gift') or now()<=c.production_expires_at)
     and c.refund_confirmed_at is null and r.id is null;
 end if;
 -- Pending/failed refunds do not start or exhaust the 30-day download window.
 return c.refund_confirmed_at is null or r.status='failed' or now()<=c.export_available_until;
end; $function$

CREATE OR REPLACE FUNCTION public.experience_storage_allowed(input_bucket text, input_name text, input_write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare pid uuid; segment text:=split_part(input_name,'/',2);
begin
 if input_bucket not in ('audio','photos','videos') or input_name like 'published/%' then return true; end if;
 select coalesce(m.book_project_id,a.book_project_id) into pid from media_assets m left join answers a on a.id=m.answer_id
   where m.storage_path=input_name limit 1;
 if pid is null and segment ~ '^[0-9a-fA-F-]{36}$' then
   select id into pid from book_projects where id=segment::uuid;
   if pid is null then select book_project_id into pid from answers where id=segment::uuid; end if;
 end if;
 if pid is null and segment='introductions' and split_part(input_name,'/',3) ~ '^[0-9a-fA-F-]{36}$' then
   select book_project_id into pid from project_introductions where id=split_part(input_name,'/',3)::uuid;
 end if;
 if pid is not null then return experience_data_allowed(pid,input_write); end if;
 -- An unassociated new file cannot evade the contract by inventing another answer ID.
 if input_write and exists(select 1 from experience_contracts c join book_projects p on p.id=c.book_project_id
   where p.owner_user_id=auth.uid() and c.payment_confirmed_at is not null) then return false; end if;
 return true;
end; $function$

CREATE OR REPLACE FUNCTION public.get_conversion_invitation_discount(input_invitation_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare i family_story_invitations%rowtype; percent integer;
begin
 select * into i from family_story_invitations where id=input_invitation_id;
 if i.id is null or (coalesce(auth.role(),'')<>'service_role'
    and (auth.uid() is null or (i.inviter_user_id is distinct from auth.uid() and i.recipient_user_id is distinct from auth.uid()))) then
  raise exception 'Invitation access required' using errcode='42501';
 end if;
 if i.pricing_policy_version='2.0' and not exists(
  select 1 from book_projects p where p.owner_user_id=i.inviter_user_id
   and p.access_status in ('paid','gifted','legacy')
   and not exists(select 1 from experience_contracts c join experience_refund_requests r on r.order_id=c.order_id where c.book_project_id=p.id)
 ) then return 0; end if;
 select integer_value into percent from commerce_settings where setting_key='family_invite_discount_percent';
 return least(100,greatest(0,coalesce(percent,0)));
end; $function$

CREATE OR REPLACE FUNCTION public.get_trial_conversion_quote(input_project_id uuid, input_order_type text, input_invitation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare p book_projects%rowtype; i family_story_invitations%rowtype; q jsonb; percent integer:=0; reduction integer:=0;
begin
 if auth.uid() is null or input_order_type is null or input_order_type not in ('self','gift') then
  raise exception 'Authentication and purchase type required' using errcode='42501'; end if;
 select * into p from book_projects where id=input_project_id;
 if p.id is null or p.owner_user_id is distinct from auth.uid() then
  raise exception 'Project owner required' using errcode='42501'; end if;
 if input_order_type='self' and p.access_status in ('paid','gifted','legacy','refunded') then raise exception 'Review existing contract first'; end if;
 q:=get_commerce_quote('self_book_v1',null,false);
 if input_invitation_id is not null then
  select * into i from family_story_invitations where id=input_invitation_id;
  if i.id is null or not coalesce((
    (input_order_type='self' and i.recipient_user_id=auth.uid() and i.recipient_project_id=p.id)
    or (input_order_type='gift' and i.inviter_user_id=auth.uid() and i.status in ('awaiting_payment','continuation_awaiting_payment'))
  ),false) then raise exception 'Invitation does not belong to this purchase' using errcode='42501'; end if;
  percent:=get_conversion_invitation_discount(i.id);
  reduction:=round(coalesce((q->>'amount_subtotal')::numeric,0)*percent/100);
 end if;
 return q||jsonb_build_object('amount_total',greatest(0,(q->>'amount_total')::integer-reduction),
  'family_price',reduction>0,'guarantee_days',case when input_order_type='gift' then 45 else 30 end);
end; $function$

CREATE OR REPLACE FUNCTION public.check_video_delivery_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'auth'
AS $function$
declare p public.book_projects%rowtype; source_path text; actual_size bigint;
begin
 if tg_op='INSERT' and not (coalesce(new.metadata,'{}') ? 'upload_complete') then raise exception 'Resumable video reservation required'; end if;
 if tg_op='UPDATE' and old.metadata ? 'upload_complete' and not (coalesce(new.metadata,'{}') ? 'upload_complete') then raise exception 'Video delivery marker cannot be removed'; end if;
 if tg_op='UPDATE' and old.metadata->>'upload_complete'='true' and new.metadata->>'upload_complete' is distinct from 'true' then raise exception 'Completed upload cannot be reopened'; end if;
 if new.metadata ? 'upload_complete' and (new.file_size_bytes is null or new.file_size_bytes<=0 or new.duration_seconds is null or new.duration_seconds<=0 or new.video_storage_path is null) then raise exception 'Video delivery metadata required'; end if;
 if new.metadata ? 'upload_complete' and new.status='ready' and new.metadata->>'upload_complete' is distinct from 'true' then raise exception 'Video upload not complete'; end if;
 select * into p from public.book_projects where id=new.book_project_id;
 if (tg_op='INSERT' or new.metadata ? 'upload_complete') and new.subject_person_id is distinct from p.subject_person_id then raise exception 'Video Person mismatch'; end if;
 if new.metadata->>'upload_complete'='true' then
   foreach source_path in array array[new.video_storage_path,new.audio_storage_path,new.poster_storage_path] loop
     if source_path is null then continue; end if;
     if source_path not like new.created_by_user_id::text||'/'||new.book_project_id::text||'/'||new.id::text||'/%' then
       raise exception 'Video path mismatch';
     end if;
     select (metadata->>'size')::bigint into actual_size from storage.objects where bucket_id='videos' and name=source_path;
     if actual_size is null or actual_size<=0 or actual_size>50331648 then raise exception 'Video upload incomplete or oversized'; end if;
     if source_path=new.video_storage_path and actual_size is distinct from new.file_size_bytes then raise exception 'Video byte count mismatch'; end if;
   end loop;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.get_book_work(input_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare w public.book_work_manifests%rowtype; ids uuid[];
begin
 if public.can_manage_book_cover(input_project_id) is distinct from true or public.experience_data_allowed(input_project_id,false) is distinct from true then raise exception 'Forbidden'; end if;
 select * into w from public.book_work_manifests where book_project_id=input_project_id;
 if w.id is null then
  select coalesce(array_agg(a.id order by a.sequence_order,a.created_at),'{}') into ids
  from public.answers a left join public.user_questions q on q.id=a.user_question_id
  join public.book_projects p on p.id=a.book_project_id
  where a.book_project_id=input_project_id and a.subject_person_id=p.subject_person_id
   and a.access_override is distinct from 'private_forever'
   and coalesce(q.meta_json->>'onboarding_group','')<>'trial_experience'
   and coalesce(q.meta_json->>'include_in_book_body','true')<>'false';
  return jsonb_build_object('answer_ids',ids,'revision',0,'confirmed_at',null);
 end if;
 return to_jsonb(w)||jsonb_build_object('publication',(
   select to_jsonb(p)||jsonb_build_object('items',(select jsonb_agg(to_jsonb(i) order by i.item_order) from voice_publication_items i where i.publication_id=p.id))
   from voice_publications p where p.work_manifest_id=w.id));
end; $function$

CREATE OR REPLACE FUNCTION public.save_book_selection(input_project_id uuid, input_answer_ids uuid[], input_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare w public.book_work_manifests%rowtype; person uuid;
begin
 if public.can_manage_book_cover(input_project_id) is distinct from true then raise exception 'Forbidden'; end if;
 perform public.assert_experience_processing(input_project_id,auth.uid());
 select subject_person_id into person from book_projects where id=input_project_id for update;
 insert into book_work_manifests(book_project_id) values(input_project_id) on conflict do nothing;
 select * into w from book_work_manifests where book_project_id=input_project_id for update;
 if w.confirmed_at is not null then raise exception 'This work is already confirmed'; end if;
 if w.revision is distinct from input_expected_revision then raise exception 'Selection changed; reload before saving'; end if;
 if input_answer_ids is null or cardinality(input_answer_ids)<>(select count(distinct x) from unnest(input_answer_ids) x)
  or exists(select 1 from unnest(input_answer_ids) x where not exists(select 1 from answers a
   where a.id=x and a.book_project_id=input_project_id and a.subject_person_id=person and a.access_override is distinct from 'private_forever')) then
  raise exception 'Invalid work selection';
 end if;
 update book_work_manifests set answer_ids=input_answer_ids,revision=revision+1 where book_project_id=input_project_id returning * into w;
 return to_jsonb(w);
end; $function$

CREATE OR REPLACE FUNCTION public.confirm_book_work(input_project_id uuid, input_expected_revision integer, input_subject_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare w public.book_work_manifests%rowtype; payload jsonb;
begin
 if public.can_manage_book_cover(input_project_id) is distinct from true or input_subject_confirmed is distinct from true then raise exception 'Subject confirmation required'; end if;
 perform public.assert_experience_processing(input_project_id,auth.uid());
 perform 1 from book_projects where id=input_project_id for update;
 select * into w from book_work_manifests where book_project_id=input_project_id for update;
 if w.id is null then raise exception 'Save selection first'; end if;
 if w.confirmed_at is not null then return to_jsonb(w); end if;
 if w.revision is distinct from input_expected_revision or cardinality(w.answer_ids)=0 then raise exception 'Review the selected stories'; end if;
 if exists(select 1 from unnest(w.answer_ids) x where not exists(select 1 from answers a join book_projects p on p.id=a.book_project_id
   where a.id=x and a.book_project_id=input_project_id and a.subject_person_id=p.subject_person_id and a.access_override is distinct from 'private_forever')) then raise exception 'Selection no longer available'; end if;
 if exists(select 1 from video_stories where book_project_id=input_project_id and (status='processing' or metadata->>'upload_complete'='false')) then raise exception 'Finish video uploads first'; end if;
 select jsonb_build_object(
  'project',to_jsonb(p),'cover',(select to_jsonb(c) from book_cover_settings c where c.book_project_id=p.id),
  'subject',(select to_jsonb(s) from persons s where s.id=p.subject_person_id),
  'answers',(select coalesce(jsonb_agg(to_jsonb(a) order by array_position(w.answer_ids,a.id)),'[]') from answers a where a.id=any(w.answer_ids)),
  'questions',(select coalesce(jsonb_agg(to_jsonb(q)),'[]') from user_questions q where q.id in(select user_question_id from answers where id=any(w.answer_ids))),
  'media',(select coalesce(jsonb_agg(to_jsonb(m) order by m.created_at),'[]') from media_assets m where m.answer_id=any(w.answer_ids) and m.book_project_id=p.id),
  'videos',(select coalesce(jsonb_agg(to_jsonb(v) order by v.slot_order),'[]') from video_stories v where v.book_project_id=p.id and v.status in('ready','failed'))
 ) into payload from book_projects p where p.id=input_project_id;
 update book_work_manifests set snapshot=payload,confirmed_at=now(),confirmed_by=auth.uid() where id=w.id returning * into w;
 return to_jsonb(w);
end; $function$

CREATE OR REPLACE FUNCTION public.finalize_experience_order(input_order_id uuid, input_checkout_session_id text, input_customer_id text, input_payment_intent_id text, input_payment_status text, input_amount_total integer, input_stripe_mode text, input_confirmed_at timestamp with time zone, input_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare c public.experience_contracts%rowtype; o public.commerce_orders%rowtype; result jsonb;
begin
 select * into o from public.commerce_orders where id=input_order_id for update;
 select * into c from public.experience_contracts where order_id=input_order_id for update;
 if o.id is null then raise exception 'Order not found'; end if;
 perform public.require_commerce_mode(input_stripe_mode);
 if o.stripe_mode is not null and o.stripe_mode is distinct from input_stripe_mode then raise exception 'Order Stripe mode mismatch'; end if;
 if c.order_id is not null then
   perform public.require_commerce_mode(input_stripe_mode);
   if input_currency is distinct from 'jpy' then raise exception 'JPY payment required'; end if;
   if o.stripe_checkout_session_id is not null and o.stripe_checkout_session_id <> input_checkout_session_id then
     raise exception 'Checkout does not belong to this order';
   end if;
   if c.refund_confirmed_at is not null or exists(select 1 from experience_refund_requests where order_id=c.order_id) then
     return jsonb_build_object('order',to_jsonb(o),'contract',to_jsonb(c),'access_stopped',true);
   end if;
   if c.payment_confirmed_at is not null then
     if input_amount_total is distinct from o.amount_total then raise exception 'Payment total mismatch'; end if;
     return jsonb_build_object('order',to_jsonb(o),'contract',to_jsonb(c),
       'gift',(select to_jsonb(g) from gift_orders g where g.commerce_order_id=o.id));
   end if;
 end if;
 result := public.finalize_commerce_order(input_order_id,input_checkout_session_id,input_customer_id,input_payment_intent_id,
   input_payment_status,input_amount_total,input_stripe_mode,input_confirmed_at);
 if c.order_id is not null then
   result := result || jsonb_build_object('contract',public.confirm_experience_payment(input_order_id,input_confirmed_at));
   update gift_orders set guarantee_status=guarantee_status where commerce_order_id=input_order_id;
   result := result || jsonb_build_object('gift',(select to_jsonb(g) from gift_orders g where g.commerce_order_id=input_order_id));
 end if;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.prepare_experience_refund(input_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare r public.experience_refund_requests%rowtype; o public.commerce_orders%rowtype;
begin
 select * into r from experience_refund_requests where id=input_request_id for update;
 select * into o from commerce_orders where id=r.order_id;
 if r.id is null or r.identity_review_required then raise exception 'Verified refund request required'; end if;
 perform public.require_commerce_mode(o.stripe_mode);
 if nullif(o.stripe_payment_intent_id,'') is null then raise exception 'Stripe payment required'; end if;
 if r.stripe_refund_id is null and r.execution_started_at < now()-interval '20 hours' then
   raise exception 'Reconcile the previous attempt before retrying'; -- Stripe may prune keys after 24h.
 end if;
 update experience_refund_requests set execution_started_at=coalesce(execution_started_at,now()) where id=r.id returning * into r;
 return to_jsonb(r)||jsonb_build_object('payment_intent_id',o.stripe_payment_intent_id,'stripe_mode',o.stripe_mode);
end; $function$

CREATE OR REPLACE FUNCTION public.get_trial_conversion_order_quote(input_project_id uuid, input_order_type text, input_invitation_id uuid DEFAULT NULL::uuid, input_discount_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare base jsonb; q jsonb; reduction integer; scope text;
begin
 base:=get_trial_conversion_quote(input_project_id,input_order_type,input_invitation_id);
 q:=get_commerce_quote('self_book_v1',input_discount_code,false);
 if q->>'campaign_id' is not null then
  select discount_scope into scope from discount_campaigns where id=(q->>'campaign_id')::uuid;
  if scope='entire_order' then
   q:=q||jsonb_build_object('amount_total',0,'discount_amount',(q->>'amount_subtotal')::integer);
  end if;
 end if;
 reduction:=least(greatest(0,(q->>'amount_total')::integer),
  greatest(0,(base->>'amount_subtotal')::integer-(base->>'amount_total')::integer));
 return q||jsonb_build_object('amount_total',greatest(0,(q->>'amount_total')::integer-reduction),
  'family_price',base->'family_price','family_discount_amount',reduction,
  'guarantee_days',base->'guarantee_days');
end; $function$
